(window.BUNKAZAI_DETAIL=window.BUNKAZAI_DETAIL||{})["c59"]=[{"id":"00006693","register_sub_id":"101","register_pk":"107676","name":"西山家住宅渡廊下","kana":"にしやまけじゅうたくわたりろうか","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府豊中市岡町南二丁目１３","lat":34.777321,"lng":135.46222376,"geo_status":"db","era":"昭和15頃","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建、瓦葺、面積15㎡","structure_material":"木造平屋建","registered":"2007.12.05(平成19.12.05)","register_no":"27 － 0435","desc":"洋館北面東寄りの玄関前から北方の主屋に向けて緩やかに降りていく１間幅の渡廊下で、桟瓦葺の切妻屋根を架ける。西面は開口のない真壁造の壁とし、重森三玲による庭園側の東面は腰壁と小壁の間を吹放ちとする。庭の築山と一体となった造りに特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006693"},{"id":"00011743","register_sub_id":"101","register_pk":"210759","name":"日本民家集落博物館河内布施の長屋門","kana":"にほんみんかしゅうらくはくぶつかんかわちふせのながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府豊中市服部緑地1-2","lat":34.779478,"lng":135.487208,"geo_status":"db","era":"江戸末期／昭和34年移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積58㎡","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"27-0679","desc":"桁行一五メートル、切妻造、本瓦葺の長屋門。やや左寄りの門口は間口三メートルで、両開板戸を吊る。右は供部屋で正面に格子窓を開き、東は蔵で扉口のみを設ける。外壁は大壁の漆喰塗で腰板張とし、正面は垂木まで塗込める。旧家の格式を伝える長屋門の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011743"},{"id":"00011745","register_sub_id":"101","register_pk":"210761","name":"日本民家集落博物館北河内の茶室","kana":"にほんみんかしゅうらくはくぶつかんきたかわちのちゃしつ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府豊中市服部緑地1-2","lat":34.778328,"lng":135.489984,"geo_status":"db","era":"嘉永4年（1851）／昭和20年代・平成17年移築","year":1851,"year_source":"db","year_min":1851,"year_max":1851,"year_label":null,"structure":"木造平屋建、茅葺、建築面積27㎡","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"27-0681","desc":"切妻造、茅葺で、四畳半の茶室と三畳の勝手からなり、濡縁をつけた貴人口は、縁端を壁として躙口や勝手の縁とを明瞭に画する。貴人口上部に櫛形窓、床脇に下地窓を穿つ。出節丸太の床柱、磨丸太の床框の他は簡明な意匠で、上層農家の茶室の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011745"},{"id":"00011744","register_sub_id":"101","register_pk":"210760","name":"日本民家集落博物館堂島の米蔵","kana":"にほんみんかしゅうらくはくぶつかんどうじまのこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府豊中市服部緑地1-2","lat":34.779308,"lng":135.487192,"geo_status":"db","era":"江戸末期／昭和25年改修、昭和35年移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積49㎡","structure_material":"土蔵造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"27-0680","desc":"桁行六間、梁間二間、切妻造、本瓦葺、妻入の土蔵。小屋組は、曲がり材の梁を折置に組む和小屋とする。正面扉口は、内側を木瓜型に縁取った観音扉と土戸及び格子戸を建て込み、正背面に一所、妻面に各二所の窓を開く。かつての堂島蔵屋敷を偲ぶ貴重な遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011744"},{"id":"00012970","register_sub_id":"101","register_pk":"368050","name":"萩原家住宅裏門","kana":"はぎわらけじゅうたくうらもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府八尾市恩智中町三丁目1","lat":34.6077,"lng":135.63179444,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造、瓦葺、間口1.4m","structure_material":"木造","registered":"2019.09.10(令和1.09.10)","register_no":"27 － 778","desc":"米蔵と納屋の間に西面して建つ切妻造桟瓦葺の門。敷地西面の石積に設けた階段上に建つ間口1.4メートルの薬医門形式で、控柱筋に門扉を設け、正面北側に袖壁を付す。側壁は漆喰塗で、腰縦板張とする。米蔵、納屋と並び建ち、敷地背面の構えを形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012970"},{"id":"00012969","register_sub_id":"101","register_pk":"368049","name":"萩原家住宅表門及び高塀","kana":"はぎわらけじゅうたくおもてもんおよびたかべい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府八尾市恩智中町三丁目1","lat":34.60759722,"lng":135.63213611,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"表門 木造、瓦葺、間口1.2m 高塀 木造、瓦葺、総延長8.8m","structure_material":"表門 木造","registered":"2019.09.10(令和1.09.10)","register_no":"27 － 777","desc":"主屋正面南半の前庭東北二面を矩折れに区切る塀と北面塀の中央に開く門。門は両脇を正面に突出するコ字形の切妻造桟瓦葺で、門扉の正背面に庇を付す。塀は切妻造桟瓦葺で、真壁漆喰塗とし、腰縦板張とする。上質かつ独特なつくりで、表構えを格調高く整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012969"},{"id":"00012967","register_sub_id":"101","register_pk":"368047","name":"萩原家住宅米蔵","kana":"はぎわらけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府八尾市恩智中町三丁目1","lat":34.60765278,"lng":135.63181667,"geo_status":"db","era":"明治42年","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積69㎡","structure_material":"土蔵造2階建","registered":"2019.09.10(令和1.09.10)","register_no":"27 － 775","desc":"敷地西北隅に東面して建つ。切妻造本瓦葺の土蔵造二階建、正面の左右に戸口を設けて吹放し下屋を通す。外壁は漆喰塗、腰縦板張で、鉢巻を廻す。内部は一室で、上下階板敷、真壁漆喰塗、和小屋とする。木綿蔵とＬ字形に連なり、背面の屋敷構えを重厚に整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012967"},{"id":"00012964","register_sub_id":"101","register_pk":"368044","name":"萩原家住宅主屋","kana":"はぎわらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府八尾市恩智中町三丁目1","lat":34.607675,"lng":135.63205833,"geo_status":"db","era":"江戸後期／明治9年頃改修・大正期増築・平成19年・同30年改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、茅葺（金属板仮葺）及び瓦葺、建築面積161㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"27 － 772","desc":"恩智神社参道と東高野街道の交差点にあるもと木綿商家。主屋は敷地前方北端に東面して建つ。大和棟で、北面を入母屋造桟瓦葺とし、正面に本瓦葺下屋を通す。北に土間、南に二列四室を配し、南面に座敷棟を突出する。門前町の風格ある景観の核をなす民家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012964"},{"id":"00012965","register_sub_id":"101","register_pk":"368045","name":"萩原家住宅巽蔵","kana":"はぎわらけじゅうたくたつみぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府八尾市恩智中町三丁目1","lat":34.60759722,"lng":135.63211667,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積19㎡","structure_material":"土蔵造2階建","registered":"2019.09.10(令和1.09.10)","register_no":"27 － 773","desc":"敷地東南隅、主屋座敷棟の東側に西面して建つ家財蔵。土蔵造二階建、切妻造本瓦葺で、外壁は漆喰塗に鉢巻三段を廻し、腰に舟板を横使いに張る。内部は上下階板敷、小屋組は棟木、母屋桁上に流し板を張る。主屋とともに街道沿いの歴史的景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012965"},{"id":"00012968","register_sub_id":"101","register_pk":"368048","name":"萩原家住宅納屋","kana":"はぎわらけじゅうたくなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府八尾市恩智中町三丁目1","lat":34.60763611,"lng":135.63187778,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積28㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"27 － 776","desc":"敷地西南隅に東面して建つ。切妻造桟瓦葺の平屋建、正面の左右に戸口を設け、吹放し下屋を付す。外壁は真壁漆喰塗、腰縦板張とする。内部は南北二室を設け、小屋組は棟木、母屋桁のみで構成する。木綿蔵、米蔵とともに背面の重厚な屋敷構えを形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012968"},{"id":"00012966","register_sub_id":"101","register_pk":"368046","name":"萩原家住宅木綿蔵","kana":"はぎわらけじゅうたくもめんぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府八尾市恩智中町三丁目1","lat":34.60776667,"lng":135.63191667,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積30㎡","structure_material":"土蔵造2階建","registered":"2019.09.10(令和1.09.10)","register_no":"27 － 774","desc":"敷地北辺、主屋背面に南面して建つ旧商品蔵。切妻造本瓦葺、土蔵造二階建の正面に吹放し下屋を付す。外壁は漆喰塗に鉢巻二段を廻し、道路側の北面に舟板を横使いに張る。内部は上下階板敷、小屋組は登梁。高野街道沿い商家の伝統的な屋敷構えを形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012966"},{"id":"00013834","register_sub_id":"101","register_pk":"507796","name":"狹間ハウス","kana":"はざまはうす","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府大阪市都島区網島町92-3他","lat":34.6962,"lng":135.52429167,"geo_status":"db","era":"昭和7年／平成18年頃改修","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造2階鉄筋コンクリート造地下1階建、瓦葺、建築面積323㎡","structure_material":"木造2階鉄筋コンクリート造地下1階建","registered":"2021.06.24(令和3.06.24)","register_no":"27 － 0818","desc":"大川河川敷堤防の堤内の傾斜地に建つ六軒長屋。傾斜に併せ地下を鉄筋コンクリート造、地上を木造二階建とし、地下は水回り、一階は台所等、二階は洋室等を配すメゾネット形式。各戸界壁の防火壁を屋根上部まで突出させた南北三〇メートルの外観が異彩を放つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013834"},{"id":"00004271","register_sub_id":"101","register_pk":"105261","name":"長谷川家住宅主屋","kana":"はせがわけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府高槻市東五百住町1-6-14","lat":34.84009402,"lng":135.60022138,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、瓦葺、建築面積136㎡","structure_material":"木造平屋建","registered":"2004.07.23(平成16.07.23)","register_no":"27 － 0298","desc":"市街地西部の集落にある。敷地北部に南面して建ち，西半に座敷４室，東半に土間を配し，つし２階を設け，屋根は入母屋造，桟瓦葺で周囲に下屋を廻す。大型の民家で，つし２階正面に木瓜形の虫籠窓を開けた目立つ外観は周囲の歴史景観に欠かせない。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004271"},{"id":"00013839","register_sub_id":"101","register_pk":"507801","name":"平池家住宅主屋","kana":"ひらいけけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府寝屋川市平池町11-1","lat":34.7689,"lng":135.62311667,"geo_status":"db","era":"安政5年(1858)／昭和29年改修、平成元年増築","year":1858,"year_source":"db","year_min":1858,"year_max":1858,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積149㎡","structure_material":"木造平屋建","registered":"2021.06.24(令和3.06.24)","register_no":"27 － 0823","desc":"入母屋造桟瓦葺。南北・東西にＴ字形に棟を通し下屋を廻す。南面中央を玄関とし、西列を座敷、台所、東列に床付座敷を二室並べ、前方に洋間を張出し東に広縁を通す。広大な旧主屋を分割し、式台玄関から座敷部分を改修して主屋としたが、重厚な構えは健在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013839"},{"id":"00013840","register_sub_id":"101","register_pk":"507802","name":"平池家住宅長屋門","kana":"ひらいけけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府寝屋川市平池町11-1","lat":34.76862222,"lng":135.62311667,"geo_status":"db","era":"文久2年(1862)／昭和2年改修","year":1862,"year_source":"db","year_min":1862,"year_max":1862,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積42㎡、塀付","structure_material":"木造平屋建","registered":"2021.06.24(令和3.06.24)","register_no":"27 － 0824","desc":"通りに南面する。本柱に冠木を載せ、柱間は板戸両開きとし、欅の一枚板の扉に八双金具、乳金具を打つ等豪壮なつくり。両脇には潜戸を備え、屋根は切妻造桟瓦葺で軒は出桁造。東西に落棟で供部屋を配したが、西は撤去して塀とした。大庄屋の表構えをつくる門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013840"},{"id":"00003457","register_sub_id":"101","register_pk":"104447","name":"廣海家住宅居間蔵","kana":"ひろうみけじゅうたくいまぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府貝塚市西町５６９他","lat":34.448975,"lng":135.35432804,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、スレート葺、建築面積23㎡","structure_material":"土蔵造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"27 － 0250","desc":"主屋の上手（西）南側に位置し，座敷と渡り廊下で接続する桁行３間，梁間２間，切妻造の２階建土蔵。現在は人造スレート葺（もと本瓦葺）で，茶器等の道具を収納している。入口は東妻にあり，南側に１，２階各１個所の窓を開ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003457"},{"id":"00003459","register_sub_id":"101","register_pk":"104449","name":"廣海家住宅下蔵","kana":"ひろうみけじゅうたくしもぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府貝塚市西町５６９他","lat":34.44897572,"lng":135.35420128,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積45㎡","structure_material":"土蔵造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"27 － 0252","desc":"中蔵と東妻を揃え，南側に半間ほど離れて建つ桁行５間，梁間２間半の２階建土蔵。内部は桁行き中央で２分割され，東西に入口を設ける。現在は仕切壁に開口を設けているが，当初は内部では行き来できない構造。小屋は地棟に登梁を投げかける形式。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003459"},{"id":"00003460","register_sub_id":"101","register_pk":"104450","name":"廣海家住宅新蔵","kana":"ひろうみけじゅうたくしんぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府貝塚市西町５６９他","lat":34.44905414,"lng":135.35399686,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積34㎡","structure_material":"土蔵造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"27 － 0253","desc":"敷地の西南隅近くにあり，東妻に出入口を開く桁行，梁間とも３間の２階建土蔵。名前の通り部材の経年から他の土蔵よりも新しく，建築年代は明治時代後半に下がると見られる。小屋は下蔵と同様地棟に登梁を投げかける形式。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003460"},{"id":"00003463","register_sub_id":"101","register_pk":"104453","name":"廣海家住宅高塀","kana":"ひろうみけじゅうたくたかべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府貝塚市西町５６９","lat":34.44872178,"lng":135.35456487,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土塀、瓦葺、延長21m","structure_material":"土塀","registered":"2003.07.01(平成15.07.01)","register_no":"27 － 0256","desc":"主屋の東南隅から南側に延び納屋に取り付く。外側は腰を縦板壁とし，水切り上方は軒蛇腹まで黒漆喰で塗り込め，内側は真壁とし，屋根は桟瓦葺とする。主屋，納屋と連続して寺内町の町並み景観を形づくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003463"},{"id":"00003458","register_sub_id":"101","register_pk":"104448","name":"廣海家住宅中蔵","kana":"ひろうみけじゅうたくなかぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府貝塚市西町５６９他","lat":34.44900114,"lng":135.354263,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積15㎡","structure_material":"土蔵造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"27 － 0251","desc":"居間蔵西側に僅かに離れて建つ，桁行２間，梁間２間の比較的小規模な土蔵。北側に入口を開き，居間蔵と同様道具類を納めている。当家で最も古い蔵との言い伝えがあり，材料の様子や痕跡から主屋よりやや先立つ時期のものと見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003458"},{"id":"00003462","register_sub_id":"101","register_pk":"104452","name":"廣海家住宅納屋","kana":"ひろうみけじゅうたくなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府貝塚市西町５６９他","lat":34.448673,"lng":135.354431,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造平屋建、瓦葺、建築面積58㎡","structure_material":"土蔵造平屋建","registered":"2003.07.01(平成15.07.01)","register_no":"27 － 0255","desc":"屋敷地の東南隅にあり，桁行６間，梁間２間半の土蔵の北正面に奥行１間の庇を付ける。内部は２部屋に分け，西半は現在床を張っているが，元は全面土間床であった。江戸時代には同所には借家があったと見られ，建築年代は明治中期に下がる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003462"},{"id":"00003461","register_sub_id":"101","register_pk":"104451","name":"廣海家住宅離れ","kana":"ひろうみけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府貝塚市西町５６９他","lat":34.44879017,"lng":135.3542829,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階一部平屋建、瓦葺、建築面積79㎡","structure_material":"木造2階一部平屋建","registered":"2003.07.01(平成15.07.01)","register_no":"27 － 0254","desc":"主屋の背面南側に新築住宅を挟んで建つ。隠居屋として建設。内部は８畳の座敷・６畳の仏間と４畳の茶室で，屋根は起り付きの桟瓦葺で東西２面に銅板葺，丸垂木の腕木庇を付け，壁に檜皮を貼り付けるなど数寄屋風の意匠を採用する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003461"},{"id":"00014501","register_sub_id":"101","register_pk":"513915","name":"深江郷土資料館別館（旧幸田家住宅）乾蔵及び塀","kana":"ふかえきょうどしりょうかんべっかん（きゅうこうだけじゅうたく）いぬいぐらおよびへい","category":"住宅","subcategory":"建築物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市東成区深江南三丁目26-3","lat":34.67033333,"lng":135.56038056,"geo_status":"db","era":"昭和10年／令和2年改修","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"乾蔵 土蔵造2階建、瓦葺、建築面積26㎡ 塀 木造、瓦葺、延長37m","structure_material":"乾蔵 土蔵造2階建","registered":"2023.02.27(令和5.02.27)","register_no":"27 - 0872","desc":"旧深江村の旧家の敷地北西隅にある乾蔵で腰を瓦葺板塀と一体とする。切妻造平入本瓦葺の土蔵造二階建。石垣と石段で入口を高くした、この地域で言う「段蔵」で洪水に備える。各階一室で小屋組は太い牛梁に登梁。西面に二連円窓を見せて歴史的景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014501"},{"id":"00014502","register_sub_id":"101","register_pk":"513916","name":"深江郷土資料館別館（旧幸田家住宅）表門","kana":"ふかえきょうどしりょうかんべっかん（きゅうこうだけじゅうたく）おもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市東成区深江南三丁目26-3","lat":34.67032778,"lng":135.5603,"geo_status":"db","era":"昭和10年／令和2年改修","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造、瓦葺、間口3.9m","structure_material":"木造","registered":"2023.02.27(令和5.02.27)","register_no":"27 - 0873","desc":"旧深江村の旧家の表門で、土蔵に挟まれて敷地北面街路に開く。両下造平入本瓦葺、出桁で軒を深く取り、扉は木柄太く八双金具等で格式整える。西袖を引違格子戸の通用口とする。石段を設けて高い地盤面の敷地内に導く。旧家の表構えで歴史的景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014502"},{"id":"00014499","register_sub_id":"101","register_pk":"513913","name":"深江郷土資料館別館（旧幸田家住宅）主屋","kana":"ふかえきょうどしりょうかんべっかん（きゅうこうだけじゅうたく）おもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市東成区深江南三丁目26-3","lat":34.67021111,"lng":135.56039722,"geo_status":"db","era":"昭和10年／令和2年改修","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造2階建、瓦葺、建築面積210㎡","structure_material":"木造2階建","registered":"2023.02.27(令和5.02.27)","register_no":"27 - 0870","desc":"奈良街道沿いの旧深江村にある旧家の主屋。入母屋造平入桟瓦葺の二階建で、街路側北面に式台玄関角屋を張り出す。一階は西側土間と床上七室の農家型平面で、二階は中廊下型平面で近代の様相を示す。一階座敷は意匠抑制的ながら用材を吟味した近代和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014499"},{"id":"00014500","register_sub_id":"101","register_pk":"513914","name":"深江郷土資料館別館（旧幸田家住宅）土蔵","kana":"ふかえきょうどしりょうかんべっかん（きゅうこうだけじゅうたく）どぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市東成区深江南三丁目26-3","lat":34.670325,"lng":135.56023889,"geo_status":"db","era":"昭和10年／同後期・令和2年改修","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積40㎡","structure_material":"土蔵造平屋建","registered":"2023.02.27(令和5.02.27)","register_no":"27 - 0871","desc":"旧深江村の旧家の土蔵で敷地北面の街路景観を構成する。切妻造本瓦葺、中央部を招き屋根状に棟を高くして中二階を設ける。東側の床は敷地内地面高で元は主屋玄関角屋と繋いだ。全体として床を三段階に設けて洪水に備えつつ、多様な用途に用いた納屋的な土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014500"},{"id":"00016682","register_sub_id":"101","register_pk":"579166","name":"福井家住宅主屋","kana":"ふくいけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府堺市西区浜寺元町六丁874","lat":34.537643,"lng":135.455313,"geo_status":"db","era":"昭和17年／令和2年改修","year":1942,"year_source":"db","year_min":1942,"year_max":1942,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積108㎡","structure_material":"木造平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"27 - 0973","desc":"浜寺公園東方の住宅地に位置する鋳物問屋の隠居主屋。入母屋造桟瓦葺で周囲に下屋を廻らす。南面西寄りに玄関を配し、東側の座敷・居間境の欄間に源氏香図をあしらう。北側の洋室は和風の棚を備えるなど、和洋の要素を巧みに取入れ、趣味性に富む隠居屋敷。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016682"},{"id":"00011361","register_sub_id":"101","register_pk":"209198","name":"藤井家住宅乾蔵","kana":"ふじいけじゅうたくいぬいぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府東大阪市東石切町五丁目500-1","lat":34.68413,"lng":135.649654,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積23㎡","structure_material":"土蔵造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"27－0659","desc":"敷地の北西隅、表門西脇に南北棟で建つ道具蔵。土蔵造二階建、桁行五・九メートル梁間三・九メートル、置屋根式の切妻造本瓦葺で東面南寄りを戸口とする。外壁漆喰塗で腰を人造石洗出し、北妻等の小窓に持送付の庇を付す。表門と一体に表構えを引立てる土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011361"},{"id":"00011364","register_sub_id":"101","register_pk":"209201","name":"藤井家住宅表門","kana":"ふじいけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府東大阪市東石切町五丁目500-1","lat":34.684111,"lng":135.649734,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積28㎡","structure_material":"木造平屋建","registered":"2016.11.29(平成28.11.29)","register_no":"27－0662","desc":"敷地北端の通り沿いに建つ。桟瓦葺屋根の東面を入母屋造とし西面は乾蔵に接続する。平面は西半を重厚な構えの門口としてケヤキ扉を開き、東半はもと供待である。外壁は中塗仕上げで腰を竪板張とし、供待に出格子窓を設ける。乾蔵と共に風格ある表構えを創る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011364"},{"id":"00011362","register_sub_id":"101","register_pk":"209199","name":"藤井家住宅米蔵","kana":"ふじいけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府東大阪市東石切町五丁目500-1","lat":34.68402327,"lng":135.64942553,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積28㎡","structure_material":"土蔵造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"27－0660","desc":"敷地南東隅に南北棟で建つ。土蔵造二階建、桁行五・九メートル梁間三・九メートル、置屋根式の切妻造桟瓦葺で、西面の戸口に下屋を設け、木瓜を表す土戸を片引とする。外壁は中塗仕上げで鉢巻を廻らし、両妻に円窓二窓を穿つ。宅地後方の景観を形成する土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011362"},{"id":"00011359","register_sub_id":"101","register_pk":"209196","name":"藤井家住宅主屋","kana":"ふじいけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府東大阪市東石切町五丁目500-1","lat":34.684031,"lng":135.649695,"geo_status":"db","era":"江戸末期／平成25改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、茅葺、建築面積129㎡、塀付","structure_material":"木造平屋建","registered":"2016.11.29(平成28.11.29)","register_no":"27－0657","desc":"生駒山西面の南北に長い敷地の北寄りに北面する。東面入母屋造、西面切妻造、茅葺（鉄板仮葺）で、桟瓦葺の下屋を廻らす。西半を土間とし、床上部は四間取系平面で表側に六畳二室を配し主室に床と仏壇を備える。斜面地に展開した集落の上層農家の好例となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011359"},{"id":"00011363","register_sub_id":"101","register_pk":"209200","name":"藤井家住宅納屋","kana":"ふじいけじゅうたくなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府東大阪市東石切町五丁目500-1","lat":34.683743,"lng":135.649646,"geo_status":"db","era":"大正期／平成13改修","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土蔵造平屋建、瓦葺、建築面積34㎡","structure_material":"土蔵造平屋建","registered":"2016.11.29(平成28.11.29)","register_no":"27－0661","desc":"離れと米蔵の間に東西棟で建つ。桁行六・九メートル梁間三・九メートル、切妻造桟瓦葺で、北面に半間幅で吹放ちの土間を張出して屋根を葺下ろし、東寄りに出入口を開く。内部は土間で、小屋組に丸太を使うなど簡素なつくりになる、屋敷構えを構成する附属屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011363"},{"id":"00011360","register_sub_id":"101","register_pk":"209197","name":"藤井家住宅離れ","kana":"ふじいけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府東大阪市東石切町五丁目500-1","lat":34.683847,"lng":135.64961,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積63㎡","structure_material":"木造平屋建","registered":"2016.11.29(平成28.11.29)","register_no":"27－0658","desc":"主屋の土間部の後方に南北棟で建ち、切妻造屋根の周囲に下屋を廻らし桟瓦葺とする。八畳座敷と次の間を並べて、東・南面に縁を設け、ガラス障子をたてる。造作等に数寄屋意匠を加味し、座敷西面には織部窓を穿つ床と、床脇を備える。瀟洒な佇まいの離れ建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011360"},{"id":"00011365","register_sub_id":"101","register_pk":"209202","name":"藤井家住宅東門及び土塀","kana":"ふじいけじゅうたくひがしもんおよびどべい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府東大阪市東石切町五丁目500-1","lat":34.6839803,"lng":135.64988238,"geo_status":"db","era":"江戸末期／昭和中期改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"東門 木造、瓦葺、間口1.9m 土塀 瓦葺、総延長61m","structure_material":"東門 木造","registered":"2016.11.29(平成28.11.29)","register_no":"27－0663","desc":"敷地東辺南寄りに開く門と、南北にのびて北は表門に接続する土塀。東門は間口一・八メートルの腕木門、切妻造桟瓦葺で、柱内に板戸両開とする。土塀は土を積み上げて表面をモルタル塗等で仕上げ、桟瓦を葺く。往時の屋敷構えと街路景観を伝える門塀である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011365"},{"id":"00010660","register_sub_id":"101","register_pk":"201234","name":"藤岡家住宅内蔵","kana":"ふじおかけじゅうたくうちぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大阪市平野区平野上町2-18他","lat":34.625866,"lng":135.552353,"geo_status":"db","era":"江戸末期／明治中期改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造平屋建、瓦葺、建築面積13㎡","structure_material":"土蔵造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"27－0615","desc":"主屋西端の小室に接続して南北棟で建つ内蔵。桁行四メートル梁間三メートル、土蔵造平屋建、切妻造本瓦葺。外壁漆喰塗で鉢巻を廻らす。明治二八年の家相鑑定により南側一間を切り縮め、内装を洋風化したとみられる。主屋とともに幕末期の様相を伝える土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010660"},{"id":"00010659","register_sub_id":"101","register_pk":"201233","name":"藤岡家住宅主屋","kana":"ふじおかけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大阪市平野区平野上町2-18他","lat":34.625845,"lng":135.552468,"geo_status":"db","era":"江戸末期／明治中期改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋一部2階建、瓦葺、建築面積154㎡","structure_material":"木造平屋一部2階建","registered":"2015.08.04(平成27.08.04)","register_no":"27－0614","desc":"平野環濠集落内で通りに南面する。建ちの低いつし二階建町家で、東寄りの土間部を落棟とし、正面は出格子や駒寄を設ける。つし部は漆喰で塗込めて横長の虫籠窓を並べ、袖壁を付ける。床上部は四間取の西に茶室などを張出す。往時の集落景観を良好に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010659"},{"id":"00010662","register_sub_id":"101","register_pk":"201236","name":"藤岡家住宅高塀","kana":"ふじおかけじゅうたくたかべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府大阪市平野区平野上町2-18他","lat":34.625811,"lng":135.552352,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造、瓦葺、延長8.8m","structure_material":"木造","registered":"2015.08.04(平成27.08.04)","register_no":"27－0617","desc":"主屋前面西端から西にのびて小庭南面を囲い、内蔵に接続する高塀。木造、切妻造桟瓦葺で、西辺の塀を一段高める。表側外観は腰高に竪板を張り、上部漆喰塗とし、内側は控え柱を立てて支持し、腰に杉皮を張る。歴史ある集落の景観形成に寄与する高塀である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010662"},{"id":"00010661","register_sub_id":"101","register_pk":"201235","name":"藤岡家住宅道具蔵","kana":"ふじおかけじゅうたくどうぐくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府大阪市平野区平野上町2-18他","lat":34.625978,"lng":135.552356,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積44㎡","structure_material":"木造2階建","registered":"2015.08.04(平成27.08.04)","register_no":"27－0616","desc":"主屋の北西に南北棟で建つ。桁行一二メートル梁間三・八メートル、土蔵造二階建、切妻造本瓦葺。外壁漆喰塗で鉢巻を廻らし、腰を杉皮張とする。上下階とも一室で東面に戸口を開き、二階に穿つ小窓の庇は繰方のある持送りで飾る。風格のある大型の道具蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010661"},{"id":"00005896","register_sub_id":"101","register_pk":"106881","name":"藤本家住宅衣装蔵","kana":"ふじともけじゅうたくいしょうぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府藤井寺市藤井寺2-3-23","lat":34.568115,"lng":135.596741,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造平屋建、瓦葺、建築面積22㎡","structure_material":"土蔵造平屋建","registered":"2006.10.18(平成18.10.18)","register_no":"27 － 0394","desc":"主屋の南方，屋敷地の西辺沿いに南北棟で建つ。桁行４間半，梁間２間規模，切妻造，本瓦葺の平屋建土蔵で，内部は２室に区画する。西面外部は，主屋の西面と一連につくり，腰を縦板張，上部を白漆喰塗とし，南妻は塗込める。門前通りの歴史的景観要素。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005896"},{"id":"00009347","register_sub_id":"101","register_pk":"194140","name":"藤野家住宅米蔵及び道具蔵","kana":"ふじのけじゅうたくこめぐらおよびどうぐぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府藤井寺市藤井寺二丁目447","lat":34.5685686,"lng":135.59766364,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造平屋建、瓦葺、建築面積51㎡","structure_material":"土蔵造平屋建","registered":"2012.08.13(平成24.08.13)","register_no":"27 － 0556","desc":"敷地南東隅、納屋の南に接続して建つ。土蔵造平屋建、桁行八・五メートル梁間四・九メートル、切妻造置屋根式の桟瓦葺で西面に土庇を設ける。東側半間を長尺物入れとし、他は北半を米蔵、南半を道具蔵とする。長屋や納屋と同様の外観で、屋敷景観を引締める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009347"},{"id":"00009344","register_sub_id":"101","register_pk":"194137","name":"藤野家住宅主屋","kana":"ふじのけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府藤井寺市藤井寺二丁目447","lat":34.56876827,"lng":135.59755954,"geo_status":"db","era":"明治26年","year":1893,"year_source":"db","year_min":1893,"year_max":1893,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積396㎡","structure_material":"木造平屋建","registered":"2012.08.13(平成24.08.13)","register_no":"27 － 0553","desc":"敷地中央に北面する。木造平屋建、建築面積三五〇平方メートル、入母屋造桟瓦葺で、周囲に下屋を廻らす。正面は黒漆喰塗で腰を簓子下見板張とし、上部は虫籠窓を穿つ。内部は東側を広い土間とし、床上部は表側に座敷を配する。風格あるつくりの大規模民家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009344"},{"id":"00009350","register_sub_id":"101","register_pk":"194143","name":"藤野家住宅正門","kana":"ふじのけじゅうたくせいもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府藤井寺市藤井寺二丁目447","lat":34.56906443,"lng":135.59748399,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造、瓦葺、間口2.2m、供部屋及び袖塀付","structure_material":"木造","registered":"2012.08.13(平成24.08.13)","register_no":"27 － 0559","desc":"敷地北正面の中央に構える、間口二・二メートルの腕木門。切妻造桟瓦葺とし、向かって右手に潜戸、左手に供部屋を設け、さらに左右に袖塀を折曲がりに延ばす。壁は鼠漆喰塗で、正面は腰を竪板張とする。堅実なつくりの表門で、風格のある表構えを形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009350"},{"id":"00009349","register_sub_id":"101","register_pk":"194142","name":"藤野家住宅鳥小屋","kana":"ふじのけじゅうたくとりごや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"大阪府","address":"大阪府藤井寺市藤井寺二丁目447","lat":34.56853984,"lng":135.5974947,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積21㎡","structure_material":"木造平屋建","registered":"2012.08.13(平成24.08.13)","register_no":"27 － 0558","desc":"敷地の南面、物置西側に東西棟で建つ。木造平屋建、桁行一一・六メートル梁間一・八メートル、片流れ招屋根付桟瓦葺である。南面は、中央の鳥小屋部分に格子を建て、東西端の物置は大壁造とする。文鳥などを飼育した鳥小屋で、旧家の暮らしぶりを伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009349"},{"id":"00009346","register_sub_id":"101","register_pk":"194139","name":"藤野家住宅納屋","kana":"ふじのけじゅうたくなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府藤井寺市藤井寺二丁目447","lat":34.56863895,"lng":135.59765698,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造平屋建、瓦葺、建築面積79㎡","structure_material":"土蔵造平屋建","registered":"2012.08.13(平成24.08.13)","register_no":"27 － 0555","desc":"主屋南東側に南北棟で建つ。土蔵造平屋建、桁行一一・七メートル梁間四・九メートル、切妻造桟瓦葺で、西面に土庇を設ける。北端の一間分を通路とし、他を納屋とする。外壁は漆喰塗で腰を竪板張とし、東門及び長屋、主屋、米蔵とともに統一的な景観を創る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009346"},{"id":"00009345","register_sub_id":"101","register_pk":"194138","name":"藤野家住宅東門及び長屋","kana":"ふじのけじゅうたくひがしもんおよびながや","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府藤井寺市藤井寺二丁目447","lat":34.56893781,"lng":135.59763985,"geo_status":"db","era":"明治7年","year":1874,"year_source":"db","year_min":1874,"year_max":1874,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積83㎡","structure_material":"木造平屋建","registered":"2012.08.13(平成24.08.13)","register_no":"27 － 0554","desc":"主屋北東側に南北棟で建つ。木造平屋建、桁行一六・八メートル梁間四・九メートル、切妻造桟瓦葺である。主屋入口近くの北寄りに東門を開き、南側に供部屋、北側に牛小屋や八畳などを配する。外壁は漆喰塗大壁で与力窓を穿ち、腰竪板張とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009345"},{"id":"00009352","register_sub_id":"101","register_pk":"194145","name":"藤野家住宅塀","kana":"ふじのけじゅうたくへい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府藤井寺市藤井寺二丁目447","lat":34.56870534,"lng":135.59736128,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土塀、瓦葺、延長19m","structure_material":"土塀","registered":"2012.08.13(平成24.08.13)","register_no":"27 － 0561","desc":"主屋西側に南北にのびる土塀で、長さ一九・二メートル高さ二・三メートルを測り、切妻造桟瓦葺である。石積みの基礎上に、厚さ約〇・四メートルで土を築き上げ、上部は水平の張出しを設けて軒をつくる。屋敷地外郭を画す土塀で、落着いた佇まいを醸す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009352"},{"id":"00009348","register_sub_id":"101","register_pk":"194141","name":"藤野家住宅物置","kana":"ふじのけじゅうたくものおき","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"明治","pref":"大阪府","address":"大阪府藤井寺市藤井寺二丁目447","lat":34.56856007,"lng":135.59760059,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造平屋建、瓦葺、建築面積14㎡","structure_material":"土蔵造平屋建","registered":"2012.08.13(平成24.08.13)","register_no":"27 － 0557","desc":"敷地の南面、道具蔵と鳥小屋の間に東西棟で建つ。土蔵造平屋建、桁行三・七メートル梁間二・八メートル、切妻造桟瓦葺である。北面半間通りを吹放し、内部は土間の一室とする。外壁は土壁で腰を竪板張とし、南北面に小窓を穿つ。屋敷地背面の景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009348"},{"id":"00009351","register_sub_id":"101","register_pk":"194144","name":"藤野家住宅露地門及び塀","kana":"ふじのけじゅうたくろじもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府藤井寺市藤井寺二丁目447","lat":34.56889438,"lng":135.59751377,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"露地門 木造、瓦葺、間口1.6m 塀 木造、瓦葺、総延長8.0m","structure_material":"露地門 木造","registered":"2012.08.13(平成24.08.13)","register_no":"27 － 0560","desc":"主屋北面の式台脇から延びる門と塀。露地門は間口一・六メートルの腕木門、切妻造桟瓦葺で、柱間に板戸引分けとする。左右の塀は総延長八メートルを測り、一文字瓦葺で、壁は真壁で東面のみ腰板を張る。前庭と主庭の間を仕切り、良好な庭空間を演出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009351"},{"id":"00005894","register_sub_id":"101","register_pk":"106879","name":"藤本家住宅裏門","kana":"ふじもとけじゅうたくうらもん","category":"住宅","subcategory":"その他工作","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府藤井寺市藤井寺2-3-23","lat":34.56801619,"lng":135.59687968,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造、瓦葺、間口2m","structure_material":"木造","registered":"2006.10.18(平成18.10.18)","register_no":"27 － 0392","desc":"屋敷地南辺の東寄りに位置し，南米蔵と東納屋の間に建つ。桁行２間，梁間１間規模，東西棟，切妻造，桟瓦葺の門で，腰を縦板張，上部を白漆喰塗とし，西側に門口を開ける。作業庭への出入口であるとともに，屋敷地南辺の景観を整える要素のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005894"},{"id":"00005893","register_sub_id":"101","register_pk":"106878","name":"藤本家住宅表門","kana":"ふじもとけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府藤井寺市藤井寺2-3-23","lat":34.56830748,"lng":135.59671358,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造、瓦葺、間口2m","structure_material":"木造","registered":"2006.10.18(平成18.10.18)","register_no":"27 － 0391","desc":"屋敷地西辺中央の北寄り，道具蔵と主屋北面西端に取り付く増築便所との間に建つ。桁行２間半，梁間１間半規模，南北棟，切妻造，桟瓦葺の門で，腰を縦板張，上部を黒漆喰塗とし，南寄りに門口，南端に通用口を開ける。門前通りの景観要素のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005893"},{"id":"00005897","register_sub_id":"101","register_pk":"106882","name":"藤本家住宅北米蔵","kana":"ふじもとけじゅうたくきたこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府藤井寺市藤井寺2-3-23","lat":34.568241,"lng":135.596924,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造平屋建、瓦葺、建築面積65㎡","structure_material":"土蔵造平屋建","registered":"2006.10.18(平成18.10.18)","register_no":"27 － 0395","desc":"主屋土間の東方，主屋東面に接して東西棟で建つ。桁行３間半，梁間５間半規模，切妻造，本瓦葺の比較的大きな平屋建土蔵で，西面北寄り，主屋土間の勘定場近くに戸口を開ける。外部は主屋と同様に軒裏まで漆喰で塗込める。現在は応接室等に使われている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005897"},{"id":"00005891","register_sub_id":"101","register_pk":"106876","name":"藤本家住宅主屋","kana":"ふじもとけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府藤井寺市藤井寺2-3-23","lat":34.568207,"lng":135.5968243,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積193㎡、便所及び塀付","structure_material":"木造平屋建","registered":"2006.10.18(平成18.10.18)","register_no":"27 － 0389","desc":"屋敷地の中央西寄りに東西棟で北面して建つ。桁行８間，梁間４間規模，切妻造，桟瓦葺のつし２階建で，棟の東端近くに煙出しを上げる。東方を土間，西方を四間取の床上部とし，北西に８畳座敷を配する。西面が通りに接し，門前通りの歴史的景観の核となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005891"},{"id":"00005895","register_sub_id":"101","register_pk":"106880","name":"藤本家住宅道具蔵","kana":"ふじもとけじゅうたくどうぐぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府藤井寺市藤井寺2-3-23","lat":34.568367,"lng":135.596725,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、瓦葺、建築面積19㎡","structure_material":"土蔵造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"27 － 0393","desc":"表門の北側，離れの西方に東西棟で建つ。桁行２間半，梁間２間規模，切妻造，本瓦葺の２階建土蔵で，南面東寄りに庇を差し掛けて戸口を設ける。外壁は白漆喰塗とし，軒部に鉢巻を廻す。門前通りに面する西面は腰を縦板張とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005895"},{"id":"00005899","register_sub_id":"101","register_pk":"106884","name":"藤本家住宅西納屋","kana":"ふじもとけじゅうたくにしなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府藤井寺市藤井寺2-3-23","lat":34.56806713,"lng":135.596741,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、瓦葺、建築面積30㎡","structure_material":"木造平屋建","registered":"2006.10.18(平成18.10.18)","register_no":"27 － 0397","desc":"衣装蔵の南方に南北棟で建つ。桁行４間，梁間２間規模，切妻造，桟瓦葺で，内部は南北２室に区画する。外部西面は衣装蔵と一連につくり，南面は東納屋の南面が延びて下屋状に納める。屋敷地西辺から南辺にかけての景観の要となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005899"},{"id":"00005892","register_sub_id":"101","register_pk":"106877","name":"藤本家住宅離れ","kana":"ふじもとけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府藤井寺市藤井寺2-3-23","lat":34.568363,"lng":135.596817,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、瓦葺、建築面積42㎡","structure_material":"木造平屋建","registered":"2006.10.18(平成18.10.18)","register_no":"27 － 0390","desc":"主屋の北方，玄関の前庭を隔てて東西棟で建つ。桁行４間半，梁間２間半，切妻造，桟瓦葺の木造平屋建で，東南隅を玄関とし，２畳土間と２畳上がり口の西方に６畳次の間と６畳座敷を並べ，西端に床・棚を設ける。北面に縁をもち，屋敷地北方の主要素になる","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005892"},{"id":"00005900","register_sub_id":"101","register_pk":"106885","name":"藤本家住宅東納屋","kana":"ふじもとけじゅうたくひがしなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府藤井寺市藤井寺2-3-23","lat":34.56802,"lng":135.59681533,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、瓦葺、建築面積19㎡","structure_material":"木造平屋建","registered":"2006.10.18(平成18.10.18)","register_no":"27 － 0398","desc":"屋敷地南辺に沿って，西納屋と裏門との間に東西棟で建つ。桁行６間，梁間１間，切妻造，桟瓦葺の細長い建造物で，東方桁行２間分を部屋とする他は作業庭側の北面を吹き放ちとする。外部南面は腰を縦板張として，屋敷地西辺沿いと連続した通り景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005900"},{"id":"00005898","register_sub_id":"101","register_pk":"106883","name":"藤本家住宅南米蔵","kana":"ふじもとけじゅうたくみなみこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府藤井寺市藤井寺2-3-23","lat":34.56805384,"lng":135.59694829,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、瓦葺、建築面積40㎡","structure_material":"土蔵造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"27 － 0396","desc":"屋敷地の東南隅，裏門の東方に南北棟で建つ。桁行４間，梁間２間半規模，切妻造，桟瓦葺の２階建土蔵で，南北２室に区画し，北室を東西２室に分け，西面に土庇を差し掛けて２戸口を開く。南側の通り沿いの妻面は腰を縦板張として，塀等と外構意匠を合わす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005898"},{"id":"00010008","register_sub_id":"101","register_pk":"196155","name":"正木記念邸腰掛待合","kana":"まさききねんていこしかけまちあい","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"大阪府","address":"大阪府泉北郡忠岡町忠岡中2-774-2他","lat":34.4946704,"lng":135.39192047,"geo_status":"db","era":"昭和27","year":1952,"year_source":"db","year_min":1952,"year_max":1952,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積5.0㎡","structure_material":"木造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"27 － 0584","desc":"主屋南東側の塀沿いに建つ。桁行四・一メートル梁間一・四メートル、木造平屋建、招造屋根の銅板葺で、北半を腰掛とし、南半の砂雪隠を落棟とする。壁は土壁で腰掛北面に矩形の窓を穿つ。軸部材や軒廻りは主として丸太を使い、落ち着いた露地空間を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010008"},{"id":"00010007","register_sub_id":"101","register_pk":"196154","name":"正木記念邸主屋","kana":"まさききねんていしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和中","pref":"大阪府","address":"大阪府泉北郡忠岡町忠岡中2-774-2他","lat":34.49480128,"lng":135.39182455,"geo_status":"db","era":"昭和24／昭和27改修","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積208㎡、塀付","structure_material":"木造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"27 － 0583","desc":"南面する入母屋造桟瓦葺で、正面に渡廊下を介して玄関を構える。西端に土間を張出し、上手前列に八畳三室を並べて縁を廻らせ、北東隅に三畳台目と六畳の茶室を設ける。主室の琵琶棚と書院を取り込んだトコや、座敷境の欄間など、室内意匠も洗練された和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010007"},{"id":"00010009","register_sub_id":"101","register_pk":"196156","name":"正木記念邸中門","kana":"まさききねんていちゅうもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和中","pref":"大阪府","address":"大阪府泉北郡忠岡町忠岡中2-774-2他","lat":34.4947156,"lng":135.39196349,"geo_status":"db","era":"昭和27","year":1952,"year_source":"db","year_min":1952,"year_max":1952,"year_label":null,"structure":"木造、檜皮葺、間口0.9m","structure_material":"木造","registered":"2014.04.25(平成26.04.25)","register_no":"27 － 0585","desc":"編笠門形式の棟門で、檜皮を葺く。丸太柱を根曲りのナグリ材の控柱で支え、竹簀戸を両開きに吊る。屋根は楕円平面で丸太垂木を放射状に配り、楕円状の小舞と広小舞、放射状のガマを重ねて軒を構成する。茶人であった施主の好みを示す、妙味豊かな露地門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010009"},{"id":"00007649","register_sub_id":"101","register_pk":null,"name":"松田家住宅主屋","kana":"まつだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府","lat":34.48514361,"lng":135.55184921,"geo_status":"db","era":"明治後期／昭和中期改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積289㎡","structure_material":"木造平屋建","registered":"2009.04.28(平成21.04.28)","register_no":"27 － 0529","desc":"通り西側の敷地前方に東面して建つ。桁行２３ｍ梁間１１ｍと規模の大きい木造つし２階建。起りのある入母屋造桟瓦葺で周囲に庇をまわし、正面中央に入母屋造の式台玄関を設ける。北側に主座敷と次の間を並べ、良質な座敷飾りを備える。近代和風建築の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007649"},{"id":"00013150","register_sub_id":"101","register_pk":"368392","name":"松宮家住宅表門","kana":"まつみやけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府枚方市杉一丁目442","lat":34.8104,"lng":135.72080556,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造平屋、瓦葺、建築面積12㎡","structure_material":"木造平屋","registered":"2019.12.05(令和1.12.05)","register_no":"27 － 0792","desc":"敷地南西に南面して建つ長屋門形式の門。西側入母屋造桟瓦葺で、東に一間一戸、潜戸付門扉を開き、西を農耕用具用の納屋とする。外壁は真壁黒漆喰塗で、腰は正面側を下見板張とし、他は竪板張とする。小規模ながら丁寧なつくりで、旧家の表構えを演出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013150"},{"id":"00013149","register_sub_id":"101","register_pk":"368391","name":"松宮家住宅米蔵","kana":"まつみやけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府枚方市杉一丁目442","lat":34.81070556,"lng":135.72069167,"geo_status":"db","era":"明治前期／昭和47年改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積16㎡","structure_material":"土蔵造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"27 － 0791","desc":"西蔵の東に南面して建つ。土蔵造二階建、置屋根形式の桟瓦葺で、正面に下屋を付す。外壁は漆喰塗で上部に鉢巻を廻し、軒際に空隙を設けて軒裏まで塗込める。内部は上下階とも一室で、小屋を和小屋組とする。西蔵と共に北側の街路景観を重厚に整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013149"},{"id":"00013147","register_sub_id":"101","register_pk":"368389","name":"松宮家住宅主屋","kana":"まつみやけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府枚方市杉一丁目442","lat":34.81060833,"lng":135.72072778,"geo_status":"db","era":"寛保4年(1744)／明治前期・昭和30年頃・同35年頃改修","year":1744,"year_source":"db","year_min":1744,"year_max":1744,"year_label":null,"structure":"木造平屋建、茅葺（金属板仮葺）、建築面積176㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"27 － 0789","desc":"市東部にある旧家の住宅。主屋は敷地中央に南面して建ち、東側を入母屋造、西側を大和棟とし、四周に下屋を廻す。内部は西に土間、東に前後二列に四室を配し、表側上手を床、仏間を設けた座敷とする。18世紀中期の様相を残す屋敷構えの中核をなす建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013147"},{"id":"00013148","register_sub_id":"101","register_pk":"368390","name":"松宮家住宅西蔵","kana":"まつみやけじゅうたくにしのくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府枚方市杉一丁目442","lat":34.81069167,"lng":135.72063333,"geo_status":"db","era":"明治中期／昭和44年改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積20㎡","structure_material":"土蔵造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"27 － 0790","desc":"敷地北西に南面して建つ諸道具を収蔵する蔵。土蔵造二階建、置屋根形式の桟瓦葺で、南面東寄に下屋を付す。外壁は漆喰塗で上部に鉢巻を廻し、腰を竪板張とする。内部は上下階とも一室で、登梁形式の小屋組とする。敷地北西の屋敷構えを形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013148"},{"id":"00005648","register_sub_id":"101","register_pk":"106636","name":"松村家住宅内塀","kana":"まつむらけじゅうたくうちべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府羽曳野市島泉二丁目１９６ 他","lat":34.57472968,"lng":135.57980288,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造、瓦葺、延長14m、門付","structure_material":"木造","registered":"2006.08.03(平成18.08.03)","register_no":"27 － 0379","desc":"主屋式台玄関の西方から南方に延び，土蔵三の北面前へ回り込む。木造，真壁造，桟瓦葺の塀で，玄関寄りに棟を高くした切妻造，桟瓦葺の庭門を設け，庭門の南に上方弓形の潜口を開ける。主屋奥座敷部の庭園を区切るとともに，玄関の前庭を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005648"},{"id":"00005643","register_sub_id":"101","register_pk":"106631","name":"松村家住宅主屋","kana":"まつむらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府羽曳野市島泉二丁目１９６ 他","lat":34.574844,"lng":135.579895,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、茅葺、建築面積311㎡","structure_material":"木造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"27 － 0374","desc":"大規模な茅葺の民家で落棟と下屋を本瓦葺とする。主体部は桁行１１間，梁行５間半規模で，東方を土間，西方床上部を４室とし，南西８畳の正面に式台を設ける。主体部の西には８畳と６畳の数寄屋風の奥座敷が取り付く。河内の大和棟の庄屋屋敷の遺構として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005643"},{"id":"00006695","register_sub_id":"101","register_pk":"107678","name":"松村家住宅主屋","kana":"まつむらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府豊中市東豊中町2-20","lat":34.80290499,"lng":135.4794354,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造2階建、瓦葺、建築面積123㎡","structure_material":"木造2階建","registered":"2007.12.05(平成19.12.05)","register_no":"27 － 0437","desc":"阪急電鉄嘱託として分譲地住宅の設計に当たった建築家下村喜三郎が自邸として設計。居間と食堂を洋室とし、要所に和室を配した平面と、妻面の独特の持送りと丸太柱による山小屋風意匠とに特徴。関西の郊外住宅の開発と設計に関与した建築家の自邸として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006695"},{"id":"00005649","register_sub_id":"101","register_pk":"106637","name":"松村家住宅外塀","kana":"まつむらけじゅうたくそとべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府羽曳野市島泉二丁目１９６ 他","lat":34.57471846,"lng":135.58032275,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造、瓦葺、延長39m","structure_material":"木造","registered":"2006.08.03(平成18.08.03)","register_no":"27 － 0380","desc":"屋敷地南辺沿いに長屋門南東端より東へ延び，屋敷地南東隅で北に折れて東辺道路沿いに延びて建つ全長約３９ｍ規模の外塀。石基礎の上に建つ真壁造，桟瓦葺の木造塀で，腰を縦板張，上部を漆喰塗で仕上げる。屋敷地東方の景観を構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005649"},{"id":"00005644","register_sub_id":"101","register_pk":"106632","name":"松村家住宅土蔵一","kana":"まつむらけじゅうたくどぞういち","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府羽曳野市島泉二丁目１９６ 他","lat":34.574959,"lng":135.5798088,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積22㎡","structure_material":"土蔵造2階建","registered":"2006.08.03(平成18.08.03)","register_no":"27 － 0375","desc":"主屋奥座敷部の北方に東西棟で建つ。桁行３間，梁間２間規模の２階建土蔵で，切妻造，本瓦葺の置屋根を載せる。石積の基礎とし，腰は竪板張，上部を白漆喰塗とし，主屋側の南面に庇を差し出して戸口を設ける。屋敷地北面の構えを形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005644"},{"id":"00005646","register_sub_id":"101","register_pk":"106634","name":"松村家住宅土蔵三","kana":"まつむらけじゅうたくどぞうさん","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府羽曳野市島泉二丁目１９６ 他","lat":34.57467473,"lng":135.57984012,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造平屋建、瓦葺、建築面積29㎡","structure_material":"土蔵造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"27 － 0377","desc":"主屋床上部の南方，長屋門の西側に接して東西棟で建つ。桁行４間，梁間３間規模，切妻造，桟瓦葺の平屋建土蔵で，北面全面に下屋庇を差し掛けて東寄りに戸口を開ける。内部は荷摺りを密に立て，登梁形式の小屋を架ける。庄屋屋敷の表構えをつくる要素のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005646"},{"id":"00005645","register_sub_id":"101","register_pk":"106633","name":"松村家住宅土蔵二","kana":"まつむらけじゅうたくどぞうに","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府羽曳野市島泉二丁目１９６ 他","lat":34.574928,"lng":135.580109,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造平屋建、瓦葺、建築面積31㎡","structure_material":"土蔵造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"27 － 0376","desc":"主屋土間の北方に東西棟で建つ。桁行４間，梁間２間規模の平屋建土蔵で，屋根は切妻造，本瓦葺とする。土蔵一と同様のつくりで，石積基礎，腰竪板張，上部白漆喰塗とし，境に水切，軒部に鉢巻を廻し，南面中央に庇を差し掛けて戸口を開ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005645"},{"id":"00005647","register_sub_id":"101","register_pk":"106635","name":"松村家住宅長屋門","kana":"まつむらけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府羽曳野市島泉二丁目１９６ 他","lat":34.574669,"lng":135.579941,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積62㎡","structure_material":"木造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"27 － 0378","desc":"主屋土間玄関の南方に位置し，東西棟で建つ。桁行７間，梁間２間規模の平屋建の長屋門で，屋根は東端を入母屋造につくり，南側を本瓦葺，北側を桟瓦葺とする。東方を蔵とし，西方には供部屋６畳２室を配し，正面に横連子窓と出窓を設けて表構えを整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005647"},{"id":"00005954","register_sub_id":"101","register_pk":"106939","name":"三ツ山家住宅旧主屋","kana":"みつやまけじゅうたくきゅうしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府大阪市中央区谷町6-9-22","lat":34.67582733,"lng":135.51602726,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"鉄筋コンクリート造地上4階建、建築面積62㎡、塔屋付","structure_material":"鉄筋コンクリート造地上4階建","registered":"2006.11.29(平成18.11.29)","register_no":"27 － 0400","desc":"長堀通りに南面して建つ。間口５．５ｍ，奥行１４ｍ，鉄筋コンクリート造４階建，塔屋付。建物背面も街路に接し，南側は北側より地盤が１階分高く，正面玄関は２階となる。外観は半円柱を巧みに見せ，縦長窓を多用する。装飾性を抑えた落ち着いた意匠とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005954"},{"id":"00006424","register_sub_id":"101","register_pk":"107407","name":"南川家住宅主屋","kana":"みなみがわけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府貝塚市新町117","lat":34.44510937,"lng":135.3531346,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階建、瓦葺、建築面積29㎡","structure_material":"木造2階建","registered":"2007.10.02(平成19.10.02)","register_no":"27 － 0430","desc":"屈曲する路地に東面し、南北棟で建つ。桁行４間、梁間２間、切妻造桟瓦葺、平入の木造２階建で、北側に土間を配し、路地に沿って４畳半２室を並べ、南面にトコを設ける。２階は板間とトコ付の座敷とする。貝塚における昭和初期の路地景観の面影を今に残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006424"},{"id":"00006425","register_sub_id":"101","register_pk":"107408","name":"南川家住宅離れ","kana":"みなみがわけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府貝塚市新町117","lat":34.44513844,"lng":135.35306211,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積60㎡","structure_material":"木造平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"27 － 0431","desc":"主屋の西方に南北棟で建つ。桁行４間半、梁間３間、切妻造、桟瓦葺、平入の木造平屋建で、北側に土間を配し、南側に４畳半とトコ付の６畳を並べる。北面に作業所、南面には納屋が附属する。貝塚市街外縁部における明治前期の住宅の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006425"},{"id":"00004882","register_sub_id":"101","register_pk":"105872","name":"南家住宅内蔵","kana":"みなみけじゅうたくうちぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府阪南市自然田1706","lat":34.34626638,"lng":135.2523381,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積22㎡","structure_material":"土蔵造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"27 － 0332","desc":"主屋の北西方に位置し，東西棟で建つ。桁行２間半，梁間２間規模，置屋根式の切妻造，本瓦葺，平入の２階建土蔵で，南面に戸口を設け，外部は腰高く縦板を張り，上部を漆喰塗とする。北面には内塀が取り付き，北西部庭園と主屋背面裏庭とを区画する要素となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004882"},{"id":"00004885","register_sub_id":"101","register_pk":"105875","name":"南家住宅表門","kana":"みなみけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府阪南市自然田1706","lat":34.34596048,"lng":135.25238476,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造、瓦葺、間口2.7m、袖塀付","structure_material":"木造","registered":"2005.11.10(平成17.11.10)","register_no":"27 － 0336","desc":"主屋の南方，辰巳蔵の西方に位置する。前面道路から間口５間，奥行約３間ほどの前庭を設けて建つ１間１戸の薬医門で，東西に脇塀を延ばし，東側に通用口を開ける。屋根は軒先を銅板葺とした本瓦葺の切妻屋根とする。屋敷正面の豪壮な構えを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004885"},{"id":"00004881","register_sub_id":"101","register_pk":"105871","name":"南家住宅主屋","kana":"みなみけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府阪南市自然田1706","lat":34.34614031,"lng":135.25226283,"geo_status":"db","era":"明治22頃／大正初期増築","year":1889,"year_source":"db","year_min":1889,"year_max":1889,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積240㎡","structure_material":"木造平屋建","registered":"2005.11.10(平成17.11.10)","register_no":"27 － 0331","desc":"屋敷地の中央東寄りに南面して建つ。東方を土間，西方を床上部とした東西棟，入母屋造，桟瓦葺のつし２階建で，西南隅に入母屋造の式台玄関を設け，玄関西方に座敷棟，背面に南北棟の台所棟を配す。旧家にふさわしい規模と構えをもち，地域の核となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004881"},{"id":"00004883","register_sub_id":"101","register_pk":"105873","name":"南家住宅外蔵","kana":"みなみけじゅうたくそとぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府阪南市自然田1706","lat":34.34620851,"lng":135.25222707,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積26㎡","structure_material":"土蔵造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"27 － 0333","desc":"主屋台所棟の北方に位置する。桁行３間，梁間２間規模，東西棟，置屋根式の切妻造，桟瓦葺，平入の２階建土蔵で，南面東寄りに戸口を開け，台所棟との間に蔵前を設ける。外部は下部を縦板張，上部を漆喰塗とし，鉢巻を廻す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004883"},{"id":"00004884","register_sub_id":"101","register_pk":"105874","name":"南家住宅辰巳蔵","kana":"みなみけじゅうたくたつみぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府阪南市自然田1706","lat":34.34598168,"lng":135.25246558,"geo_status":"db","era":"大正10頃","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積78㎡","structure_material":"土蔵造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"27 － 0334","desc":"主屋の東南方に南北棟で建つ。桁行７間，梁間３間半規模の２階建土蔵で，屋根は切妻造，桟瓦葺で軒先を銅板葺とする。酒造業を営んだ時期は米蔵として使用され，西面と南面に戸口を開ける。東・南面が道路に接した比較的大規模な蔵で，屋敷地東南角の核となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004884"},{"id":"00004886","register_sub_id":"101","register_pk":"105876","name":"南家住宅土塀","kana":"みなみけじゅうたくどべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府阪南市自然田1706、1708","lat":34.34588852,"lng":135.25208408,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土塀、瓦葺、延長77m","structure_material":"土塀","registered":"2005.11.10(平成17.11.10)","register_no":"27 － 0337","desc":"表門前庭から西方へ向けて屋敷地南辺沿いに約５０ｍ，及び屋敷地内の垣内と庭園との境界南部約２５ｍに残る。石敷基礎の上に築かれた土塀で，頂部に桟瓦葺の小屋根を載せる。表門，辰巳蔵とともに街区の歴史的景観をかたちづくる要素になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004886"},{"id":"00004999","register_sub_id":"101","register_pk":"105989","name":"南家住宅納屋","kana":"みなみけじゅうたくなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府阪南市自然田1707","lat":34.346104,"lng":135.25195372,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積28㎡","structure_material":"木造平屋建","registered":"2005.11.10(平成17.11.10)","register_no":"27 － 0335","desc":"垣内と呼ばれる屋敷地西側の農作業場に位置する。桁行３間，梁間２間規模，切妻造，本瓦葺の木造平屋建で，西面に半間の庇を葺き下ろし，南面に廻し込む。内部は南北に２室に区画し，北方を土間とする。作業小屋として使われ，垣内の往時の様相を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004999"},{"id":"00014879","register_sub_id":"101","register_pk":"519139","name":"三好家住宅主屋","kana":"みよしけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府南河内郡太子町大字太子1816","lat":34.51804444,"lng":135.63981111,"geo_status":"db","era":"天保3年（1832）／明治中期増築","year":1832,"year_source":"db","year_min":1832,"year_max":1832,"year_label":null,"structure":"木造2階建、瓦葺、建築面積307㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"27 - 0906","desc":"叡福寺南大門の南東に位置する医家の主屋。敷地中央に東面するつし二階建入母屋造本瓦葺で北東に角屋を延ばす。東面中央に式台を構え、南を土間、北を床上とし、北西に床構え付き座敷を配し縁を付す。式台の差鴨居上に家紋付蟇股を飾り、医家の格式を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014879"},{"id":"00002068","register_sub_id":"101","register_pk":"103058","name":"免山篤家住宅石垣","kana":"めざんあつしけじゅうたくいしがき","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府茨木市佐保1161","lat":34.87281219,"lng":135.52524747,"geo_status":"db","era":"大正1","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"石造、延長19m","structure_material":"石造","registered":"2000.12.04(平成12.12.04)","register_no":"27 － 0129","desc":"屋敷西側の急峻な坂に面して築く。玉石状の自然石を用い坂に沿って緩やかに曲面を造る巧みな野面積みで，南端部では高さ５メートルに及ぶ。保存状態の良さは石積み技術の高さを示し，屋敷のみでなく集落を代表する景観を特徴付けるものとして価値が高い。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002068"},{"id":"00002064","register_sub_id":"101","register_pk":"103054","name":"免山篤家住宅勝手","kana":"めざんあつしけじゅうたくかって","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"大阪府","address":"大阪府茨木市佐保1161","lat":34.87291386,"lng":135.52537983,"geo_status":"db","era":"大正1","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積12㎡","structure_material":"木造平屋建","registered":"2000.12.04(平成12.12.04)","register_no":"27 － 0125","desc":"主屋土間部分の背後に位置する水廻り施設で，内部に井戸と流しを備え，床は全面石敷きとする。丸太の柱を半間毎に立て周囲中塗仕上げの壁を造り，屋根は切妻造，桟瓦葺である。小規模で簡素な建物であるが，屋敷の勝手廻りを構成する重要な施設である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002064"},{"id":"00002066","register_sub_id":"101","register_pk":"103056","name":"免山篤家住宅北及び東塀","kana":"めざんあつしけじゅうたくきたおよびひがしべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府茨木市佐保1161","lat":34.87293945,"lng":135.52543276,"geo_status":"db","era":"大正1","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造、瓦葺、延長25m","structure_material":"木造","registered":"2000.12.04(平成12.12.04)","register_no":"27 － 0127","desc":"敷地北面の道路及び主屋東の露地境に築く。半間毎に柱を立て桟瓦葺屋根をのせ，外側上半を黒漆喰塗，下半を竪板張とする。木部を赤く塗り，棟の屈曲部に留蓋風の役瓦を載せるなど意匠を凝らし，勝手，便所の壁も一連の仕上げとして屋敷表側の構えを整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002066"},{"id":"00002061","register_sub_id":"101","register_pk":"103051","name":"免山篤家住宅主屋","kana":"めざんあつしけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府茨木市佐保1161","lat":34.87284504,"lng":135.525345,"geo_status":"db","era":"大正1","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造平屋建、茅葺、建築面積154㎡","structure_material":"木造平屋建","registered":"2000.12.04(平成12.12.04)","register_no":"27 － 0122","desc":"主屋は当地方における伝統的な農家の形式を踏襲するが，座敷廻りには床，棚，付書院を完備し，高い技術による瀟洒な意匠になる。集落の中心にあって歴史的景観の核となるとともに，土間，勝手廻りに至るまで建築当初の形式がそのまま保存され価値が高い。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002061"},{"id":"00002062","register_sub_id":"101","register_pk":"103052","name":"免山篤家住宅土蔵一","kana":"めざんあつしけじゅうたくどぞういち","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府茨木市佐保1161","lat":34.87288142,"lng":135.5252649,"geo_status":"db","era":"大正1","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積23㎡","structure_material":"土蔵造平屋建","registered":"2000.12.04(平成12.12.04)","register_no":"27 － 0123","desc":"屋敷北西隅に北及び西面を道路に面して建つ。切妻造，桟瓦葺，土蔵造で，上方約三分の一を漆喰塗，その下を杉焼板張りとする。平屋だが立ちの高い特徴ある外観をもち，敷地北西隅を限る目立つ位置にあり，屋敷構えを構成する重要な建物となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002062"},{"id":"00002063","register_sub_id":"101","register_pk":"103053","name":"免山篤家住宅土蔵二","kana":"めざんあつしけじゅうたくどぞうに","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府茨木市佐保1161","lat":34.87289642,"lng":135.52532524,"geo_status":"db","era":"大正1","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積16㎡","structure_material":"土蔵造平屋建","registered":"2000.12.04(平成12.12.04)","register_no":"27 － 0124","desc":"敷地北西隅の土蔵の東に接続して北側の道路に面して建つ。西の土蔵と同形式だが，桁行が短く棟高，軒高もやや低い。小規模だが軒蛇腹を造るなど本格的な造りで，西の土蔵と一体となって屋敷北面西半の景観を整える主要な要素となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002063"},{"id":"00002065","register_sub_id":"101","register_pk":"103055","name":"免山篤家住宅納屋","kana":"めざんあつしけじゅうたくなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府茨木市佐保1161","lat":34.87273966,"lng":135.525528,"geo_status":"db","era":"明治38","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積41㎡","structure_material":"木造平屋建","registered":"2000.12.04(平成12.12.04)","register_no":"27 － 0126","desc":"敷地南東隅に建つ。正面南半に下屋を付属し，これより北に下屋の屋根と一連の庇を持ち送りで支えて付ける。切妻造，桟瓦葺，外壁は大壁で，軒も垂木，母屋形を見せて塗り込める。作業用の施設だが，屋敷への露地の正面にあり，外観の意匠に配慮している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002065"},{"id":"00002067","register_sub_id":"101","register_pk":"103057","name":"免山篤家住宅西塀","kana":"めざんあつしけじゅうたくにしべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府茨木市佐保1161","lat":34.87280973,"lng":135.5252536,"geo_status":"db","era":"大正1","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造、瓦葺、延長11m","structure_material":"木造","registered":"2000.12.04(平成12.12.04)","register_no":"27 － 0128","desc":"屋敷地の西側道路に面した石垣上に築いた塀。急峻な坂に面する西側では，道路との段差が小さい北半部分は高く，それより南の高い石垣上は低く築く。半間毎に柱を立て桟瓦葺屋根をのせ，西面では石垣とともに屋敷構えの重要な構成要素となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002067"},{"id":"00014640","register_sub_id":"101","register_pk":"515182","name":"八木家住宅主屋","kana":"やぎけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府寝屋川市香里本通町978-7他","lat":34.78395556,"lng":135.63340278,"geo_status":"db","era":"昭和5年／昭和34年頃・同58年改修","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階建、瓦葺一部銅板葺、建築面積193㎡","structure_material":"木造2階建","registered":"2023.08.07(令和5.08.07)","register_no":"27 - 0884","desc":"香里園駅東の住宅街に建つ藤井厚二設計の木造二階建桟瓦葺の住宅。和風の要素を幾何学的な構成や椅子式の生活様式に合わせて再構成した意匠や、通気筒により空気の循環に配慮するなど、聴竹居で完成をみた藤井の環境共生住宅の特徴を極めて良い状態で残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014640"},{"id":"00014642","register_sub_id":"101","register_pk":"515184","name":"八木家住宅蔵","kana":"やぎけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府寝屋川市香里本通町978-7他","lat":34.784,"lng":135.63356389,"geo_status":"db","era":"昭和5年／昭和16年改修","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積10㎡","structure_material":"土蔵造平屋建","registered":"2023.08.07(令和5.08.07)","register_no":"27 - 0886","desc":"近代住宅地の香里園にある住宅の倉庫。切妻造平入桟瓦葺の土蔵造平屋建。当初は下男部屋と一体で真壁造で、戦争に備えて防火構造に改修。出入口は鉄扉を吊り、舟底天井、背面窓一箇所開ける。抱合せの方杖の補強は、規模の割に念入りで戦時中の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014642"},{"id":"00014641","register_sub_id":"101","register_pk":"515183","name":"八木家住宅下男部屋","kana":"やぎけじゅうたくげなんべや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府寝屋川市香里本通町978-7他","lat":34.78405278,"lng":135.63356111,"geo_status":"db","era":"昭和5年／昭和16年・平成8年改修","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積13㎡","structure_material":"木造平屋建","registered":"2023.08.07(令和5.08.07)","register_no":"27 - 0885","desc":"近代住宅地の香里園に所在する住宅の付属建物。お抱えの馬丁が寝泊まりした住居で、当初は蔵と一体。切妻造桟瓦葺、真壁造竪板張仕上。内部は四畳半押入便所付。南面出入口は馬屋に向けたもので、後年賃貸のために道路側に玄関を設けた。屋敷外郭を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014641"},{"id":"00014643","register_sub_id":"101","register_pk":"515185","name":"八木家住宅門及び塀","kana":"やぎけじゅうたくもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府寝屋川市香里本通町978-7他","lat":34.78405833,"lng":135.63337222,"geo_status":"db","era":"昭和5年／平成28年改修","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"門 木造、銅板葺、間口2.0m 塀 木造、銅板葺、総延長22m","structure_material":"門 木造","registered":"2023.08.07(令和5.08.07)","register_no":"27 - 0887","desc":"香里園にある屋敷北辺道路に面し、主屋正面に位置する表門と、道路沿い東に延びる板塀。門は木柱に扁平な兜巾金物を被せ、門扉は框戸で下半を竪格子として緩やかに内外を仕切る。塀は竪板壁、竹一本の欄間、銅板葺屋根とする。主屋と意匠を揃える近代和風。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014643"},{"id":"00014194","register_sub_id":"101","register_pk":"508824","name":"安田家住宅主屋","kana":"やすだけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府柏原市大字青谷2160","lat":34.57509167,"lng":135.65884167,"geo_status":"db","era":"延享3年(1746)頃／明治前期増築・昭和前期改修","year":1746,"year_source":"db","year_min":1746,"year_max":1746,"year_label":null,"structure":"木造平屋建、茅葺、建築面積232㎡","structure_material":"木造平屋建","registered":"2022.02.17(令和4.02.17)","register_no":"27-0844","desc":"龍田道沿いの集落に建つ旧庄屋の茅葺農家。平屋建、入母屋造平入で、下屋を本瓦葺とする。当初は二列五室の奥深い間取りで、上手奥座敷列を増築した。広い土間を煙返しの梁でカマヤとニワに区画する。敷鴨居に突止め溝を用いるなど河内地方の古式を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014194"},{"id":"00002805","register_sub_id":"101","register_pk":"103795","name":"山田家住宅表門","kana":"やまだけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府泉南市新家3148-1","lat":34.372692,"lng":135.296295,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、間口5m","structure_material":"木造","registered":"2002.06.25(平成14.06.25)","register_no":"27 － 0185","desc":"山田家は南側の前面道路から主屋前庭に至るまで２つの門をくぐる厳重な配置を採る。表門はこのうち敷地外に直接開く桁行１０ｍ，梁間３ｍ規模，切妻造，本瓦葺の長屋門。門部分は東端に取り，部屋部分には外面の各柱間に与力窓を付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002805"},{"id":"00002801","register_sub_id":"101","register_pk":"103791","name":"山田家住宅玄関棟","kana":"やまだけじゅうたくげんかんとう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"大阪府","address":"大阪府泉南市新家3148-1","lat":34.37305436,"lng":135.29612069,"geo_status":"db","era":"文久3頃","year":1863,"year_source":"db","year_min":1863,"year_max":1863,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積45㎡","structure_material":"木造平屋建","registered":"2002.06.25(平成14.06.25)","register_no":"27 － 0181","desc":"主屋下手西側に接続し，主屋上手西側にある角座敷に至る正式な入口。式台付きの玄関と主屋接続部にある小玄関からなり，玄関背後に４畳半の茶室を設ける。南側正面に入母屋の破風を突き出し，庄屋の格式をあらわす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002801"},{"id":"00002803","register_sub_id":"101","register_pk":"103793","name":"山田家住宅米蔵","kana":"やまだけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府泉南市新家3148-1","lat":34.37282642,"lng":135.29633296,"geo_status":"db","era":"嘉永7","year":1854,"year_source":"db","year_min":1854,"year_max":1854,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積39㎡、西面及び北面土庇付","structure_material":"土蔵造平屋建","registered":"2002.06.25(平成14.06.25)","register_no":"27 － 0183","desc":"桁行９．８ｍ，梁間３．９ｍ，切妻造，平屋建，本瓦葺の土蔵で，西正面に腕木庇，北面に土庇を設ける。内部は３室に分かれ，それぞれの部屋に正面からの戸を開く。主屋前庭東側の敷地外からアクセスしやすい場所にあり，年貢の米を収納したことが窺われる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002803"},{"id":"00002800","register_sub_id":"101","register_pk":"103790","name":"山田家住宅主屋","kana":"やまだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府泉南市新家3148-1","lat":34.373108,"lng":135.296265,"geo_status":"db","era":"文久3","year":1863,"year_source":"db","year_min":1863,"year_max":1863,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積119㎡、南面土庇及び塀付","structure_material":"木造平屋一部2階建","registered":"2002.06.25(平成14.06.25)","register_no":"27 － 0180","desc":"山田家は小栗街道(熊野古道)近くの新家中村集落にあって，代々庄屋を勤めた豪農である。本瓦葺，２階建の主屋は文久３年の再建であるが，２階に前身主屋のものと見られる古材を残し，間取りも主体部は喰違い３間取系の古式な形式を残す点に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002800"},{"id":"00003273","register_sub_id":"101","register_pk":"104263","name":"山田家住宅主屋","kana":"やまだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府貝塚市北町10-5","lat":34.44931967,"lng":135.35818718,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積183㎡","structure_material":"木造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"27 － 0218","desc":"願泉寺北側の堀之町筋北側にある町家。主屋は間口８間奥行１２間の敷地一杯に建つ切妻造桟瓦葺（前面庇本瓦葺）で，２階壁面を銅板張とするが，以前は本瓦葺，漆喰塗りであった。玄関に摺上げ大戸を残し，建物全体も良好に維持されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003273"},{"id":"00002802","register_sub_id":"101","register_pk":"103792","name":"山田家住宅台所棟","kana":"やまだけじゅうたくだいどころとう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"大阪府","address":"大阪府泉南市新家3148-1","lat":34.372993,"lng":135.296402,"geo_status":"db","era":"江戸末期／大正10改築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積90㎡","structure_material":"木造平屋建","registered":"2002.06.25(平成14.06.25)","register_no":"27 － 0182","desc":"主屋下手東側に接続する本瓦葺の炊事場。内部は土間床で井戸と竈があり，棟上には煙出しがある。現在のものは大正１０年に改築されたものであるが，台所廻りの設備が良く残り，上層農家の炊事場の様子を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002802"},{"id":"00002804","register_sub_id":"101","register_pk":"103794","name":"山田家住宅土蔵","kana":"やまだけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府泉南市新家3148-1","lat":34.37329465,"lng":135.296204,"geo_status":"db","era":"寛政6","year":1794,"year_source":"db","year_min":1794,"year_max":1794,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積27㎡、東面庇付","structure_material":"土蔵造2階建","registered":"2002.06.25(平成14.06.25)","register_no":"27 － 0184","desc":"桁行５．９ｍ，梁間４．６ｍ規模，２階建，本瓦葺の平入土蔵で，東正面中央に庇を持ち，屋根は置屋根形式である。米蔵と対照的に主屋北側の奥まった位置にあり，内向きの家財などを納めたと見られる。山田家の建物の中ではもっとも建築年代が古い。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002804"},{"id":"00002807","register_sub_id":"101","register_pk":"103797","name":"山田家住宅土塀","kana":"やまだけじゅうたくどべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府泉南市新家3148-1","lat":34.3733235,"lng":135.29637804,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土塀、瓦葺、総延長82m","structure_material":"土塀","registered":"2002.06.25(平成14.06.25)","register_no":"27 － 0187","desc":"敷地南側の表門両側，敷地北側，及び主屋北側の土蔵から矩の手に西側に延びる位置にある４個所のそれぞれ版築造，本瓦葺の土塀。敷地北側の土塀には中央の門が含まれる。強固な構造で，道なりの高低差を石積で処理し，屋敷の外構をよく整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002807"},{"id":"00013608","register_sub_id":"101","register_pk":"504962","name":"山野家住宅主屋及び塀","kana":"やまのけじゅうたくおもやおよびへい","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府大阪市北区西天満三丁目2-7","lat":34.69561111,"lng":135.50718889,"geo_status":"db","era":"大正7年頃／昭和8年改修","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"主屋 木造2階建、瓦葺、建築面積93㎡、塀 木造、瓦葺、延長14m","structure_material":"主屋 木造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"27 － 0812","desc":"西天満の繁華街に位置する。二階建切妻造桟瓦葺。通りに面して主屋と一体となった塀及び玄関を建て、前庭をはさんで主屋を建てる。主屋は通り土間沿いに三室並べ、二階は座敷と洋風書斎とする。大阪の中心部に残るいわゆる大塀造の町家として貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013608"},{"id":"00003121","register_sub_id":"101","register_pk":"104111","name":"山野家住宅蔵","kana":"やまのけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府交野市私部7-11-2","lat":34.788891,"lng":135.684158,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土蔵造2階建、瓦葺、建築面積39㎡","structure_material":"土蔵造2階建","registered":"2003.01.31(平成15.01.31)","register_no":"27 － 0210","desc":"主屋奥座敷裏の縁に接続する蔵。土蔵造，３階建，切妻造で，本瓦葺の置屋根とする。什物を保管する道具蔵として主屋移築時に新築されたといい，外部は漆喰で塗り込め堅牢な造りとする。酒蔵一，四と並んで通り側の特徴ある屋敷構えに欠くことのできない建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003121"},{"id":"00003117","register_sub_id":"101","register_pk":"104107","name":"山野家住宅主屋","kana":"やまのけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府交野市私部7-11-2","lat":34.78878428,"lng":135.68431215,"geo_status":"db","era":"江戸末期／大正末期移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積366㎡","structure_material":"木造平屋建","registered":"2003.01.31(平成15.01.31)","register_no":"27 － 0206","desc":"造り酒屋の住宅の主屋で敷地中央西寄りに建つ。寝屋川市にあった江戸末期の民家が移築されたもので，一部改造があるものの土間，６間取りの居室部，これに続く落屋根の座敷部全体が旧状を良く残す。大規模で重厚な造りになり，屋敷構えの中心を構成する建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003117"},{"id":"00003122","register_sub_id":"101","register_pk":"104112","name":"山野家住宅土塀","kana":"やまのけじゅうたくどべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府交野市私部7-11-2","lat":34.78865151,"lng":135.68405796,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土塀、瓦葺、延長47m","structure_material":"土塀","registered":"2003.01.31(平成15.01.31)","register_no":"27 － 0211","desc":"長屋門西脇から住宅蔵の南に至る敷地境界を折れ曲がりに仕切る。側溝際の切石積基壇上に築かれた土塀で，頂部に蛇腹を回し本瓦葺の屋根をかける。基礎石を置き，北端部も蛇腹を回し込むなど全体に丁寧な仕事になり，中塗仕上げにより独特の風致を造っている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003122"},{"id":"00003118","register_sub_id":"101","register_pk":"104108","name":"山野家住宅長屋門","kana":"やまのけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府交野市私部7-11-2","lat":34.78857759,"lng":135.6843098,"geo_status":"db","era":"明治期／昭和初期移築","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造平屋建、瓦葺、建築面積123㎡","structure_material":"木造平屋建","registered":"2003.01.31(平成15.01.31)","register_no":"27 － 0207","desc":"敷地南西部に南面して建つ。入母屋造，桟瓦葺，桁行１８間の長大な建物で，正面側の軒を出桁造とし，垂木とともに漆喰で塗り込める。堅牢で上質な造りであるとともに，表には高く下見板を張り，２箇所の出格子窓，虫籠窓などが配され変化に富んだ外観を造る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003118"},{"id":"00013146","register_sub_id":"101","register_pk":"368291","name":"山本家住宅北土蔵及び表門","kana":"やまもとけじゅうたくきたどぞうおよびおもてもん","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府吹田市佐井寺二丁目4035","lat":34.78216389,"lng":135.51748611,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"土蔵 土蔵造平屋建、瓦葺、建築面積39㎡ 門 木造、瓦葺、間口2.0m","structure_material":"土蔵 土蔵造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"27 － 0788","desc":"敷地北辺の通路に沿って建つ。西側の北土蔵と東側の門からなる。北土蔵は土蔵造桟瓦葺で、外壁は軒裏まで漆喰で塗込めて鉢巻二段を廻し、腰を竪板張りとする。内部は一室で、壁、天井に金属板を張る。入母屋造桟瓦葺の門と共に、豪壮な表構を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013146"},{"id":"00002429","register_sub_id":"101","register_pk":"103419","name":"山本家住宅主屋","kana":"やまもとけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府南河内郡太子町太子1773","lat":34.517761,"lng":135.639328,"geo_status":"db","era":"大正3","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造2階建、瓦葺、建築面積244㎡","structure_material":"木造2階建","registered":"2001.10.12(平成13.10.12)","register_no":"27 － 0154","desc":"山本家住宅は聖徳太子の廟所叡福寺門前にあり，竹の内街道に面して長大な間口を構える。主屋は間口１０間半，奥行き４間半の大規模な２階建で，緩やかに起る大屋根が叡福寺境内や街道からのアイストップになっている。絵様付きの方杖など細部も優秀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002429"},{"id":"00013144","register_sub_id":"101","register_pk":"368289","name":"山本家住宅主屋","kana":"やまもとけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府吹田市佐井寺二丁目4035","lat":34.78205833,"lng":135.51728889,"geo_status":"db","era":"江戸後期／昭和6年・平成29年改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、茅葺（銅板仮葺）、建築面積261㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"27 － 0786","desc":"市中央部にある肝煎を務めた旧家。主屋は入母屋造茅葺(銅板仮葺)で棟を瓦葺とし、正面中央に式台玄関を設け、四周に下屋を廻す。内部は北に土間、南に前後二列六室を配し、表側上手を床を設けて簀の子天井とした座敷とする。旧家の屋敷構えの中核を成す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013144"},{"id":"00002432","register_sub_id":"101","register_pk":"103422","name":"山本家住宅高塀","kana":"やまもとけじゅうたくたかべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府南河内郡太子町太子1773","lat":34.51784443,"lng":135.63919081,"geo_status":"db","era":"大正3","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造、瓦葺、延長34m","structure_material":"木造","registered":"2001.10.12(平成13.10.12)","register_no":"27 － 0157","desc":"北面の竹の内街道沿い西寄りから西面の蔵一北西隅にかけて矩の手に敷地を限る真壁の高塀。北面東端から南方の主屋上手に接続する腕木門を設ける。蔵二，主屋とともに街道側の伝統的なファサードを構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002432"},{"id":"00002430","register_sub_id":"101","register_pk":"103420","name":"山本家住宅西蔵","kana":"やまもとけじゅうたくにしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府南河内郡太子町太子1773","lat":34.517666,"lng":135.639175,"geo_status":"db","era":"大正3","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積47㎡","structure_material":"土蔵造平屋建","registered":"2001.10.12(平成13.10.12)","register_no":"27 － 0155","desc":"敷地西南隅にある置屋根形式の蔵で，北側に戸前の庇，それ以外の三方には水切りの腕木庇をつける。他の建物が桟瓦葺であるとは異なり本瓦葺で，置屋根の登梁や母屋，垂木なども漆喰で塗籠める本格的な土蔵である。屋敷の構成要素として欠かせない存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002430"},{"id":"00002431","register_sub_id":"101","register_pk":"103421","name":"山本家住宅東蔵","kana":"やまもとけじゅうたくひがしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府南河内郡太子町太子1773","lat":34.517761,"lng":135.639557,"geo_status":"db","era":"大正3","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積34㎡","structure_material":"土蔵造2階建","registered":"2001.10.12(平成13.10.12)","register_no":"27 － 0156","desc":"主屋東方にあり，街道に面して建つ土蔵。南，西面に庇を設け南庇を濡縁とし，内部は東西２室に分かれ，西側は蔵座敷とする。主屋とは木戸を介して接続し，河内地方の街道筋の変化に富んだ町家景観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002431"},{"id":"00013145","register_sub_id":"101","register_pk":"368290","name":"山本家住宅東土蔵","kana":"やまもとけじゅうたくひがしどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府吹田市佐井寺二丁目4035","lat":34.78205833,"lng":135.51751944,"geo_status":"db","era":"大正12年／昭和47年頃改修","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積39㎡","structure_material":"土蔵造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"27 － 0787","desc":"敷地東辺北寄りに西面して建つ。置屋根形式の土蔵造桟瓦葺で、西面南寄りに庇、北面に下屋を付す。外壁は漆喰塗で上部に鉢巻二段を廻し、腰を竪板張とする。内部は上下階とも一室で、壁に金属板を張り、和小屋組とする。敷地北東の屋敷景観の一角を成す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013145"},{"id":"00010677","register_sub_id":"101","register_pk":"201251","name":"横内家住宅奥座敷棟","kana":"よこうちけじゅうたくおくざしきとう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"大阪府","address":"大阪府東大阪市四条町433","lat":34.658032,"lng":135.644829,"geo_status":"db","era":"明治30年／昭和5年移築","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積58㎡","structure_material":"木造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"27－0632","desc":"主屋上手に廊下を介して接続し、通り沿いに建つ。東面入母屋造、西面寄棟造桟瓦葺で、下屋を廻らす。十畳主室と六畳を並べ、北東面に縁を設ける。主室には座敷飾を備え、室境に筬欄間をたてて飾る。開放的で瀟洒な離れ建築で、集落内の街路景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010677"},{"id":"00010678","register_sub_id":"101","register_pk":"201252","name":"横内家住宅表門","kana":"よこうちけじゅうたくおもてもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府東大阪市四条町433","lat":34.658038,"lng":135.645032,"geo_status":"db","era":"明治前期／昭和前期改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積33㎡","structure_material":"木造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"27－0633","desc":"主屋前面に構える長屋門形式の門。切妻造桟瓦葺で中央東寄りの門口と東端の納屋を落棟とする。門口は板戸両開きの西脇に潜戸を吊る。外壁は鼠漆喰で仕上げて与力窓や出格子を配し、腰に簓子下見板を張る。西室内装部は数寄屋座敷とする。重厚な表構えを創る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010678"},{"id":"00010676","register_sub_id":"101","register_pk":"201250","name":"横内家住宅主屋","kana":"よこうちけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府東大阪市四条町433","lat":34.657966,"lng":135.644968,"geo_status":"db","era":"明治前期／昭和前期改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積149㎡","structure_material":"木造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"27－0631","desc":"東西敷地に北面して建つ。土間部を落棟とした切妻造桟瓦葺で下屋を廻らし、外壁は竪板張や格子を見せる。床上部は食違い四間取とし土間寄りに式台を構える。昭和前期に文人の当主により数寄屋風意匠に改修されており、格式と風趣を兼備した上質な民家である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010676"},{"id":"00010680","register_sub_id":"101","register_pk":"201254","name":"横内家住宅土塀","kana":"よこうちけじゅうたくどべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府東大阪市四条町433","lat":34.658073,"lng":135.64481,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土塀、瓦葺、延長31m","structure_material":"土塀","registered":"2015.08.04(平成27.08.04)","register_no":"27－0635","desc":"敷地北西面に矩折れに廻る、延長三一メートルの塀。大振りの自然石を野面積とした石垣に厚さ約〇・六メートルの築地塀を築き、壁を漆喰塗、屋根桟瓦葺とする。路面の高低により西面石垣が最も高く、約一・九メートルを測る。城郭を思わせる風格を備える土塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010680"},{"id":"00010679","register_sub_id":"101","register_pk":"201253","name":"横内家住宅露地門及び塀","kana":"よこうちけじゅうたくろじもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府東大阪市四条町433","lat":34.658019,"lng":135.644965,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"露地門 木造、瓦葺、間口1.1m 塀 木造、瓦葺、延長2.3m","structure_material":"露地門 木造","registered":"2015.08.04(平成27.08.04)","register_no":"27－0634","desc":"主屋式台の西側柱と長屋門の南西隅柱の間に建ち、前庭と主庭を画す露地門と塀。切妻造桟瓦葺で南塀の屋根は門と一連とし北塀を落棟とする。門は腕木門で桟唐戸内開きである。塀は鼠漆喰仕上げとし欄間に横桟を通す。玉石敷や植栽とともに庭空間に趣を添える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010679"},{"id":"00009800","register_sub_id":"101","register_pk":"195629","name":"横山家住宅隠居棟","kana":"よこやまけじゅうたくいんきょとう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"大阪府","address":"大阪府高槻市城北町1-88他","lat":34.84779389,"lng":135.62069769,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、瓦葺、建築面積85㎡","structure_material":"木造2階建","registered":"2013.12.24(平成25.12.24)","register_no":"27 － 0575","desc":"主屋東側に、通りから後退して建ち、木造二階建、切妻造桟瓦葺である。二階縁手摺に吹寄菱格子をあしらい、縁下の垂壁に緩いアーチ状の枠を使う。正面出入口に舞良戸をたて、内部は座敷や茶室を田字形に配し、造作は数寄屋風を加味する。瀟洒な意匠の隠居所。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009800"},{"id":"00016411","register_sub_id":"101","register_pk":"536478","name":"横山家住宅主屋","kana":"よこやまけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":null,"lat":null,"lng":null,"geo_status":"missing","era":"昭和9年／昭和60年代改修","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造2階建、瓦葺、建築面積167㎡","structure_material":"木造2階建","registered":"2025.11.17(令和7.11.17)","register_no":"27 - 0950","desc":"庚申街道の西側に位置する実業家の住宅主屋。敷地の西に二階建寄棟造東西棟の和館、東に半切妻造南北棟の洋館を配し、屋根はパルメット紋の鬼瓦などを用いた桟瓦葺とする。外壁はモルタル掻落仕上で出隅に水平帯を飾るなど、セセッション風意匠をみせる主屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016411"},{"id":"00009801","register_sub_id":"101","register_pk":"195630","name":"横山家住宅蔵","kana":"よこやまけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府高槻市城北町1-88他","lat":34.84793666,"lng":135.62057277,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積21㎡","structure_material":"土蔵造2階建","registered":"2013.12.24(平成25.12.24)","register_no":"27 － 0576","desc":"敷地後方、納屋西隣に南北棟で建つ。土蔵造二階建、桁行五メートル梁間四・一メートル、切妻造本瓦葺で、南妻面を戸口として庇を付ける。外壁は漆喰塗で細い鉢巻を廻らし、竪板を腰高に張る。南面二階と西面上下階に庇付の小窓を穿つ。屋敷構えを整える土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009801"},{"id":"00009799","register_sub_id":"101","register_pk":"195628","name":"横山家住宅主屋","kana":"よこやまけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府高槻市城北町1-88他","lat":34.84778318,"lng":135.62057277,"geo_status":"db","era":"天保6／昭和46改修","year":1835,"year_source":"db","year_min":1835,"year_max":1835,"year_label":null,"structure":"木造2階建、瓦葺、建築面積171㎡","structure_material":"木造2階建","registered":"2013.12.24(平成25.12.24)","register_no":"27 － 0574","desc":"旧高槻城下町に南面して建ち、木造二階建、寄棟造及び切妻造桟瓦葺で、前面に下屋を設ける。一階正面に出格子をたて、二階は大壁造で軒先まで塗込め、格子窓を穿つ。北西側に平屋で上質な造作の離れを接続する。城下で唯一現存する近世郷宿の遺構である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009799"},{"id":"00009802","register_sub_id":"101","register_pk":"195631","name":"横山家住宅納屋","kana":"よこやまけじゅうたくなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府高槻市城北町1-88他","lat":34.84792238,"lng":135.62067627,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積63㎡","structure_material":"土蔵造2階建","registered":"2013.12.24(平成25.12.24)","register_no":"27 － 0577","desc":"敷地後方、蔵の東隣に東西棟で建つ。土蔵造二階建、桁行一〇メートル梁間五メートル、切妻造桟瓦葺で、南面に下屋を設け、東寄りに漬物部屋を張出す。外壁漆喰塗で軒まで塗込め、二階南面に格子窓を穿つ。重厚な趣の納屋で、蔵とともに風格ある景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009802"},{"id":"00009803","register_sub_id":"101","register_pk":"195632","name":"横山家住宅門及び塀","kana":"よこやまけじゅうたくもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府高槻市城北町1-87他","lat":34.84771478,"lng":135.62063404,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"門 木造、瓦葺、間口1.3m 塀 木造、瓦葺、総延長7.3m","structure_material":"門 木造","registered":"2013.12.24(平成25.12.24)","register_no":"27 － 0578","desc":"隠居棟正面中央に開く門と、その左右にのびる塀。門は間口一・三メートルの腕木門、切妻造、桟瓦葺である。塀は総延長七・三メートルで、腕木で桁を受け、板軒の上に桟瓦を葺く。壁は真壁で腰に竪板を張る。隠居棟前庭を囲う門と塀で、城下町の風情を醸す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009803"},{"id":"00007251","register_sub_id":"101","register_pk":"108233","name":"吉田家住宅北長屋","kana":"よしだけじゅうたくきたながや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"大阪府","address":"大阪府大阪市北区豊崎1-47","lat":34.71042094,"lng":135.50390594,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造2階建、瓦葺、建築面積110㎡","structure_material":"木造2階建","registered":"2008.07.08(平成20.07.08)","register_no":"27 － 0480","desc":"主屋の北方、道路に北面して建つ。木造２階建、Ｌ字型に折れ曲がる切妻造桟瓦葺。内部を３戸に分け、西側２戸は同平面で、北西に玄関を配し、２階はトコをもつ六畳と四畳の２部屋とする。北面中央の窓には木製の手摺と庇を残し、当時の面影を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007251"},{"id":"00007255","register_sub_id":"101","register_pk":"108237","name":"吉田家住宅北二軒長屋","kana":"よしだけじゅうたくきたにけんながや","category":"住宅","subcategory":"建築物","type_guess":"塀","type_guess_confidence":"low","period":"大正","pref":"大阪府","address":"大阪府大阪市北区豊崎1-50","lat":34.71012729,"lng":135.50417844,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造2階建、瓦葺、建築面積61㎡、塀付","structure_material":"木造2階建","registered":"2008.07.08(平成20.07.08)","register_no":"27 － 0484","desc":"敷地東側、東長屋と南二軒長屋の間に建つ。木造２階建、切妻造桟瓦葺で、南北２戸に分ける。東長屋と同様に、主屋と意匠を揃えた高塀をめぐらし、その北寄りに門を開く。主屋とともに、往時の路地空間の面影を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007255"},{"id":"00007248","register_sub_id":"101","register_pk":"108230","name":"吉田家住宅主屋","kana":"よしだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府大阪市北区豊崎1-47","lat":34.710274,"lng":135.50397382,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造2階建、瓦葺、建築面積116㎡","structure_material":"木造2階建","registered":"2008.07.08(平成20.07.08)","register_no":"27 － 0477","desc":"敷地中央西寄りに建ち、周囲を長屋が囲む。木造２階建、東西棟の東入母屋造、西切妻造、桟瓦葺。東側はもと通り土間で、西側を四間取の居室とする。正面に式台玄関を設け、座敷には座敷飾りを備える。大正期の都市住宅の形態をよく留めている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007248"},{"id":"00007249","register_sub_id":"101","register_pk":"108231","name":"吉田家住宅土蔵","kana":"よしだけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府大阪市北区豊崎1-47","lat":34.71035588,"lng":135.50392136,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土蔵造2階建、瓦葺、建築面積11㎡","structure_material":"土蔵造2階建","registered":"2008.07.08(平成20.07.08)","register_no":"27 － 0478","desc":"主屋の北西に建つ。桁行３．９ｍ梁間３．０ｍ、土蔵造２階建、切妻造本瓦葺で、南面に桟瓦葺の庇を付ける。外壁は漆喰仕上げで、下階に鳥居型の扉枠を漆喰で表し、掛子塗の扉を吊る。扉内側に木瓜形の造出し。都市部での、主屋と一体的に建てられた土蔵の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007249"},{"id":"00007252","register_sub_id":"101","register_pk":"108234","name":"吉田家住宅西長屋","kana":"よしだけじゅうたくにしながや","category":"住宅","subcategory":"建築物","type_guess":"塀","type_guess_confidence":"low","period":"大正","pref":"大阪府","address":"大阪府大阪市北区豊崎1-48","lat":34.71006262,"lng":135.50404827,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造2階建、瓦葺、建築面積79㎡、塀付","structure_material":"木造2階建","registered":"2008.07.08(平成20.07.08)","register_no":"27 － 0481","desc":"主屋の南側に路地を挟んで建つ。南北棟の桟瓦葺で、北入母屋造、南切妻造。木造２階建とし、南北に４戸を配する。各戸とも基本平面は同じで、東面南寄りを玄関とし、１階奥を台所とする。２階は六畳１室。東面には桁行全長に軒庇を付け、当初の形式を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007252"},{"id":"00007253","register_sub_id":"101","register_pk":"108235","name":"吉田家住宅東長屋","kana":"よしだけじゅうたくひがしながや","category":"住宅","subcategory":"建築物","type_guess":"塀","type_guess_confidence":"low","period":"大正","pref":"大阪府","address":"大阪府大阪市北区豊崎1-47","lat":34.71029803,"lng":135.50415256,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造2階建、瓦葺、建築面積141㎡、塀付","structure_material":"木造2階建","registered":"2008.07.08(平成20.07.08)","register_no":"27 － 0482","desc":"主屋東側に路地を挟んで建つ。南北棟の切妻造桟瓦葺。木造２階建で、南北４戸に分ける。各戸とも基本平面は同じで、西面に主屋と意匠を揃えた高塀をめぐらし、北寄りに門を開く。１階は台所や四畳半、２階に２室を配す。路地沿いに建つ長屋の面影を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007253"},{"id":"00007254","register_sub_id":"101","register_pk":"108236","name":"吉田家住宅南二軒長屋","kana":"よしだけじゅうたくみなみにけんながや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"大阪府","address":"大阪府大阪市北区豊崎1-50","lat":34.71003768,"lng":135.50419856,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造2階建、瓦葺、建築面積64㎡","structure_material":"木造2階建","registered":"2008.07.08(平成20.07.08)","register_no":"27 － 0483","desc":"敷地東側の南端に建つ。木造２階建、切妻造桟瓦葺。南北の２戸に分けるが、基本平面は同様である。西面南寄りに入口を設ける。２階の西面壁を半間後退させ、屋根と庇は緩やかに起らせる。西面外壁には当初仕様とみられるスクラッチタイル貼を残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007254"},{"id":"00007250","register_sub_id":"101","register_pk":"108232","name":"吉田家住宅門及び高塀","kana":"よしだけじゅうたくもんおよびたかべい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府大阪市北区豊崎1-47","lat":34.71022082,"lng":135.50405131,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"門 木造、瓦葺、間口2.7m 塀 木造、瓦葺、延長42m","structure_material":"門 木造","registered":"2008.07.08(平成20.07.08)","register_no":"27 － 0479","desc":"主屋の前庭を囲い、座敷前面を東西に区画する庭塀も含む。延長４２ｍ、木造、一文字瓦葺で、腰を竪板張とし、小壁は鼠色の漆喰仕上げとする。主屋入口の正面では、壁面を後退させて、潜戸を開き、瓦葺の庇を付け、格調高い屋敷構えを形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007250"},{"id":"00006222","register_sub_id":"101","register_pk":"107206","name":"吉田酒造蔵","kana":"よしだしゅぞうくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府池田市栄本町2622","lat":34.826294,"lng":135.424759,"geo_status":"db","era":"明治11頃","year":1878,"year_source":"db","year_min":1878,"year_max":1878,"year_label":null,"structure":"土蔵造3階建、瓦葺、建築面積20㎡","structure_material":"土蔵造3階建","registered":"2007.05.15(平成19.05.15)","register_no":"27 － 0417","desc":"主屋北側に隣接して建つ。桁行２間半，梁間２間の土蔵造３階建で，本瓦葺，妻入，切妻造とする。外観は白漆喰塗，腰縦板張とし，壁面の四周に水切瓦を廻らす。たちの高い土蔵の頂部に，鍾馗と宝珠を付けた大型の鬼瓦を載せる。街路景観において際立った存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006222"},{"id":"00006221","register_sub_id":"101","register_pk":"107205","name":"吉田酒造主屋","kana":"よしだしゅぞうしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府池田市栄本町2622","lat":34.826195,"lng":135.424759,"geo_status":"db","era":"明治11頃","year":1878,"year_source":"db","year_min":1878,"year_max":1878,"year_label":null,"structure":"木造2階建、瓦葺、建築面積204㎡","structure_material":"木造2階建","registered":"2007.05.15(平成19.05.15)","register_no":"27 － 0416","desc":"市中心部に位置する。方５間規模，つし２階建，本瓦葺，平入で，南を切妻造，北を入母屋造とする。正面２階は黒漆喰塗仕上げで虫籠窓を穿ち，両側に袖卯建を付ける。通り土間に沿って部屋を２列に配する大型町家で，醸造業で繁栄した往時の佇まいを今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006221"},{"id":"00006223","register_sub_id":"101","register_pk":"107207","name":"吉田酒造塀","kana":"よしだしゅぞうへい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府池田市栄本町2622","lat":34.82627174,"lng":135.42469428,"geo_status":"db","era":"明治11頃","year":1878,"year_source":"db","year_min":1878,"year_max":1878,"year_label":null,"structure":"木造、瓦葺、延長8.8m、門付","structure_material":"木造","registered":"2007.05.15(平成19.05.15)","register_no":"27 － 0418","desc":"主屋の西側，街路に面して築かれる。ほぼコ字形平面の折曲り延長８．８ｍの高塀で，南折曲り部分に庭門を付ける。基礎は花崗岩布積，腰を縦板張とし，真壁には黒漆喰を用い，屋根は一文字瓦で葺く。全体として良質かつ端正なつくりとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006223"},{"id":"00014267","register_sub_id":"101","register_pk":"509657","name":"吉野家住宅主屋","kana":"よしのけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府岸和田市本町129他","lat":34.45948333,"lng":135.36806389,"geo_status":"db","era":"昭和4年","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造2階建、瓦葺、建築面積160㎡","structure_material":"木造2階建","registered":"2022.06.29(令和4.06.29)","register_no":"27 - 0858","desc":"岸和田城下の紀州街道に面して歴史的景観を留める米穀商の町家。豪壮な二階建、切妻造平入本瓦葺で、西側落棟は倉庫で入母屋造とする。西寄りに玄関を設けて通り土間とし、東側に表から店間、仏間、座敷を配す。木柄が太く、肥松一枚板の建具など贅を凝らす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014267"},{"id":"00003455","register_sub_id":"101","register_pk":"104445","name":"吉村家住宅衣装蔵","kana":"よしむらけじゅうたくいしょうぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府貝塚市西町12-7","lat":34.44871096,"lng":135.35516472,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積44㎡","structure_material":"土蔵造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"27 － 0248","desc":"主屋下手に増築された座敷部の南に接続する２階建，切妻造，本瓦葺の土蔵。入口は北側の妻に取り，茶室南側の廊下に開く。桁行４間，梁間２間半の比較的大規模な蔵で，西側には座敷用の便所を庇で掛け出す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003455"},{"id":"00003454","register_sub_id":"101","register_pk":"104444","name":"吉村家住宅道具蔵","kana":"よしむらけじゅうたくどうぐぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府貝塚市西町12-7","lat":34.44873876,"lng":135.35530028,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積39㎡","structure_material":"土蔵造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"27 － 0247","desc":"主屋下手の背後にある２階建，切妻造，本瓦葺の土蔵。増築された主屋の座敷に接するが，入口は西側妻の中庭側にとり，腕木庇を取り付ける。桁行４間，梁間２間の規模で，床下を石積で高く上げ，地下に穴蔵を設ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003454"},{"id":"00003283","register_sub_id":"101","register_pk":"104273","name":"利齋家住宅離れ","kana":"りさいけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府貝塚市北町18-3","lat":34.449928,"lng":135.357559,"geo_status":"db","era":"大正13頃","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積91㎡","structure_material":"木造平屋一部2階建","registered":"2003.03.18(平成15.03.18)","register_no":"27 － 0228","desc":"主屋北側に中庭を隔てて建つ。１階を８畳と６畳の続き座敷とし，２階は西側に寄せて建て，一室の洋間とする。兵庫県南部地震後外壁や洋間のクロスを張り替えるなど改変があるが，暖炉のタイルや窓のステンドグラス，照明器具等本格的な装飾意匠が現存する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003283"},{"id":"00002954","register_sub_id":"101","register_pk":"103944","name":"和田家住宅内蔵","kana":"わだけじゅうたくうちぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府岸和田市宮本町29-4","lat":34.46109502,"lng":135.37448508,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積22㎡","structure_material":"土蔵造2階建","registered":"2002.08.21(平成14.08.21)","register_no":"27 － 0192","desc":"主屋背面に平行して建つ。木造，２階建，平入で，屋根は切妻造，本瓦葺，外壁は漆喰塗とし，背面と側面の腰を縦板で覆う。主屋側１階に戸口，２階両妻に窓をそれぞれ設ける。窓庇の持送り板の繰形，妻面まで廻した軒蛇腹など，丁寧なつくりの土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002954"},{"id":"00002959","register_sub_id":"101","register_pk":"103949","name":"和田家住宅内塀","kana":"わだけじゅうたくうちべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府岸和田市宮本町29-4","lat":34.46095049,"lng":135.37422967,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"土塀、瓦葺、延長21m、門付","structure_material":"土塀","registered":"2002.08.21(平成14.08.21)","register_no":"27 － 0197","desc":"Ｌ字形平面で玄関のある主屋突出部から，屋敷正面の外塀まで延びる延長約２５ｍの内塀。主屋側に１間棟門をつくり，他は真壁造で壁上部に横長窓を開ける。主屋前面の庭園空間と玄関前のアプローチ空間を適切に分節しており，大邸宅に欠かせない附属施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002959"},{"id":"00002962","register_sub_id":"101","register_pk":"103952","name":"和田家住宅勝手口門","kana":"わだけじゅうたくかってぐちもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府岸和田市宮本町29-4","lat":34.46096388,"lng":135.37446033,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造、瓦葺、間口1.8m、両側板塀7m付","structure_material":"木造","registered":"2002.08.21(平成14.08.21)","register_no":"27 － 0200","desc":"屋敷東辺を区切る東塀の北端にあり，主屋の台所側に通じる門。形式は１間棟門で，切妻造・本瓦葺屋根を架け，左右に折曲がりで本瓦葺の袖塀が附属する。屋根には起りがあり，袖塀は腰を縦板で覆うなど，屋敷の脇門ながら数寄屋風の瀟洒な造形である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002962"},{"id":"00012591","register_sub_id":"101","register_pk":"367885","name":"和田家住宅主屋","kana":"わだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府河内長野市野作町280","lat":34.451599,"lng":135.560791,"geo_status":"geocoded","era":"明治前期／昭和49年頃改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、茅葺（金属板仮葺）及び瓦葺、建築面積210㎡","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"27 － 0764","desc":"市中心部の農家主屋で、敷地中央に東面して建つ。切妻造茅葺(鋼板仮葺)で、両端に本瓦葺の落棟が接続する。北に土間、南に前後二列各三室を配し、前列中央に式台玄関、南端の表に正面向き、裏に背面向きの座敷を設ける。大和棟の大型民家で集落の象徴的存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012591"},{"id":"00002953","register_sub_id":"101","register_pk":"103943","name":"和田家住宅主屋","kana":"わだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府岸和田市宮本町29-4","lat":34.461048,"lng":135.374374,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階建、瓦葺一部銅板葺、建築面積390㎡","structure_material":"木造2階建","registered":"2002.08.21(平成14.08.21)","register_no":"27 － 0191","desc":"南西を正面とする総２階建，入母屋造，本瓦葺の豪壮な建物。Ｌ字形平面で，突出部は重厚な漆喰塗とし，入母屋造の玄関を設ける。良材をふんだんに用い，趣向を凝らした洋室，洗練された座敷飾を備えた客間，吹き抜けの内玄関など，昭和初期の和風住宅の優作。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002953"},{"id":"00002955","register_sub_id":"101","register_pk":"103945","name":"和田家住宅外蔵","kana":"わだけじゅうたくそとぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府岸和田市宮本町29-4","lat":34.46085794,"lng":135.3742929,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積115㎡","structure_material":"土蔵造2階建","registered":"2002.08.21(平成14.08.21)","register_no":"27 － 0193","desc":"屋敷地の北隅に独立してあり，家具や建具等を収納した。木造，２階建，平入で，屋根は切妻造，本瓦葺，荒塗の外壁は背面と両側面の腰を縦板で覆う。主屋側に戸口３カ所を設け，戸前庇を架ける。１階は３室に仕切るが，２階は１室とした土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002955"},{"id":"00002960","register_sub_id":"101","register_pk":"103950","name":"和田家住宅外塀","kana":"わだけじゅうたくそとべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府岸和田市宮本町29-4","lat":34.46106783,"lng":135.37406205,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"煉瓦造、瓦葺、延長45m","structure_material":"煉瓦造","registered":"2002.08.21(平成14.08.21)","register_no":"27 － 0198","desc":"主屋の正面，屋敷南辺を区切る延長約４６ｍの塀。屋敷南には小城川（現在は暗渠）が流れ，高い谷積の石垣を築いた上に，煉瓦造・モルタル塗でつくり，桟瓦の屋根を架ける。屋敷の外構をかたちづくるとともに，川沿いであったかつての景観を今に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002960"},{"id":"00002957","register_sub_id":"101","register_pk":"103947","name":"和田家住宅長屋門","kana":"わだけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府岸和田市宮本町29-4","lat":34.46096,"lng":135.374451,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積36㎡","structure_material":"木造平屋建","registered":"2002.08.21(平成14.08.21)","register_no":"27 － 0195","desc":"主屋の玄関正面，屋敷の南隅に建つ。重厚な入母屋造，本瓦葺で，通例の形式を簡略して正面右半分に門口を設け，左半分は床張の伴部屋とする。真壁造で，腰を簓子下見板張，壁中央に出格子窓を付け，門口には欅を多用する。大邸宅の正面景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002957"},{"id":"00002956","register_sub_id":"101","register_pk":"103946","name":"和田家住宅離れ","kana":"わだけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府岸和田市宮本町29-4","lat":34.46119794,"lng":135.3743999,"geo_status":"db","era":"大正期／昭和5移築","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、瓦葺、建築面積31㎡","structure_material":"木造平屋建","registered":"2002.08.21(平成14.08.21)","register_no":"27 － 0194","desc":"主屋の西方に独立して建つ。入母屋造，桟瓦葺で，内部は各８畳の座敷と次の間及び台所からなる。高欄付の縁を２面に廻し，また段差のある地形を懸造風に処理している。床・棚・付書院は派手さを押さえた上質なつくりになり，全体に繊細な比例の書院造である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002956"},{"id":"00002961","register_sub_id":"101","register_pk":"103951","name":"和田家住宅東塀","kana":"わだけじゅうたくひがしべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府岸和田市宮本町29-4","lat":34.46085954,"lng":135.37438594,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"土塀、瓦葺、延長25m","structure_material":"土塀","registered":"2002.08.21(平成14.08.21)","register_no":"27 － 0199","desc":"屋敷の東辺を区切る延長約２５ｍの塀。南は長屋門東妻に接し，緩やかな起伏があるので中途で段違いとし，北端で勝手口門の脇塀に接する。布積の石垣を築いた上に，土塀をつくり，本瓦の屋根を架ける。高低差を巧みに処理し，屋敷の外構をかたちづくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002961"},{"id":"00002958","register_sub_id":"101","register_pk":"103948","name":"和田家住宅待合","kana":"わだけじゅうたくまちあい","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府岸和田市宮本町29-4","lat":34.4610001,"lng":135.374542,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積3㎡","structure_material":"木造平屋建","registered":"2002.08.21(平成14.08.21)","register_no":"27 － 0196","desc":"主屋の東側にあり，屋敷の東辺に設けられた勝手口門に接して建っている。桁行２間程度の大きさになり，切妻造，本瓦葺で北面側を開放とする。荒壁風で，腰掛を設け，主屋側には下地窓をつくる。大邸宅の生活の様相を示す施設で，茶室待合と同様の意匠をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002958"},{"id":"00005889","register_sub_id":"101","register_pk":"106874","name":"亘家住宅米蔵","kana":"わたりけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府吹田市内本町2-13-10","lat":34.75689931,"lng":135.52315824,"geo_status":"db","era":"明治40","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積40㎡","structure_material":"土蔵造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"27 － 0387","desc":"長屋門の東北方に位置し，南北棟で建つ。桁行３間半，梁間２間規模，切妻造，本瓦葺，置屋根形式の２階建土蔵で，基礎は石積，腰高く縦板を張り廻し，西面北寄りに庇を差し掛け，石段を設けて戸口を開く。長屋門に隣接して建ち，重厚な出入口の外観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005889"},{"id":"00005835","register_sub_id":"101","register_pk":"106821","name":"亘家住宅主屋","kana":"わたりけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府吹田市内本町2-13-10","lat":34.756824,"lng":135.522842,"geo_status":"db","era":"江戸中／江戸後・明治27・40増築","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中","structure":"木造平屋一部2階建、茅葺一部瓦葺、建築面積406㎡","structure_material":"木造平屋一部2階建","registered":"2006.10.18(平成18.10.18)","register_no":"27 － 0383","desc":"東西に長い不整形敷地の中央に南面して建つ。桁行１０間，梁間６間半規模の主体部の西面に２階建の新座敷，北西方に内蔵，北東方に漬物・味噌部屋を張り出すなど複雑な平面をもつ。茅葺西側を大和棟風のつくりとし，東面の北方を一段高くしているのが特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005835"},{"id":"00005888","register_sub_id":"101","register_pk":"106873","name":"亘家住宅土蔵","kana":"わたりけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府吹田市内本町2-13-10","lat":34.75681304,"lng":135.52265114,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積46㎡","structure_material":"土蔵造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"27 － 0386","desc":"屋敷地の北西隅部，主屋新座敷の北方に位置し，東西棟で建つ。桁行３間半，梁間２間規模，切妻造，本瓦葺の２階建土蔵で，南面全面に土庇を差し掛け，中央やや西寄りに戸口を開き，裏白戸を建て込む。内蔵などとともに裏庭空間を構成する要素である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005888"},{"id":"00005866","register_sub_id":"101","register_pk":"106852","name":"亘家住宅長屋門","kana":"わたりけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府吹田市内本町2-13-10","lat":34.75678996,"lng":135.52318131,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積64㎡","structure_material":"木造平屋建","registered":"2006.10.18(平成18.10.18)","register_no":"27 － 0385","desc":"屋敷地の東南隅部，東方の道路から西に引き込まれた私道の突き当たりに南北棟で建つ。切妻造，桟瓦葺，腰を縦板張とした真壁造の長屋門で，北方に門口を開け，南方に部屋をとる。主屋の土間と離れの式台に通じ，屋敷の表構えに欠くことのできない存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005866"},{"id":"00005865","register_sub_id":"101","register_pk":"106851","name":"亘家住宅離れ","kana":"わたりけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府吹田市内本町2-13-10","lat":34.756699,"lng":135.522964,"geo_status":"db","era":"江戸後期／江戸末期増改造","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積70㎡","structure_material":"木造平屋建","registered":"2006.10.18(平成18.10.18)","register_no":"27 － 0384","desc":"主屋の南方に位置する。桁行３間半，梁間２間半規模，入母屋造，桟瓦葺の平屋建で，北面東寄りに３畳と便所を角屋状に突き出す。もと３室並びの直屋であったが，のちに東面に式台を設け，主屋と渡廊下で繋がれた。庄屋宅の玄関棟としての役割を果たした建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005865"},{"id":"00002806","register_sub_id":"101","register_pk":"103796","name":"山田家住宅長屋門","kana":null,"category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府泉南市新家3148-1","lat":34.372803,"lng":135.296173,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積148㎡","structure_material":"木造平屋建","registered":"2002.06.25(平成14.06.25)","register_no":"27 － 0186","desc":"山田家住宅の２つの門のうち内側の門で表門とともに２重の構えをなす。敷地幅ほぼ一杯の間口約３０ｍに達する切妻造，本瓦葺の長屋門で，門部分は表門に対応して東寄りに開ける。長大な屋根が庄屋の屋敷の景観を特徴づける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002806"},{"id":"00003996","register_sub_id":"101","register_pk":"104986","name":"池田谷家住宅主屋","kana":null,"category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府泉佐野市大西1-1640","lat":34.41061714,"lng":135.31336826,"geo_status":"db","era":"昭和2頃／昭和24増築","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積156㎡","structure_material":"木造平屋建","registered":"2004.03.02(平成16.03.02)","register_no":"27 － 0272","desc":"大阪を中心に活動した建築家池田谷久吉設計の自邸。寄棟造，桟瓦葺の木造平屋建で，北の玄関から南方へ接客用の和室を配し，中央部を居室，西方を水回りとする。玄関東脇には寺院古材を用いた３畳茶室を設ける。軒下の漆喰塗小壁が高く，独特の外観を呈する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003996"},{"id":"00003997","register_sub_id":"101","register_pk":"104987","name":"池田谷家住宅蔵","kana":null,"category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府泉佐野市大西1-1640","lat":34.41065244,"lng":135.3133351,"geo_status":"db","era":"昭和2頃","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階建、瓦葺、建築面積17㎡","structure_material":"木造2階建","registered":"2004.03.02(平成16.03.02)","register_no":"27 － 0273","desc":"主屋の北面西端に接続する蔵。木造２階建，切妻造，桟瓦葺で土蔵風に鉢巻を巡らす。木格子付の引違いガラス窓は幅１間と大きめである。主屋との間に土間通路を設け，１階を物置とし，２階は６畳大板間の書斎である。１階の瓦庇は，主屋の庇と高さを揃える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003997"},{"id":"00004004","register_sub_id":"101","register_pk":"104994","name":"中山家住宅炭蔵綿蔵","kana":null,"category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府松原市別所6-623","lat":34.588821,"lng":135.564606,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積42㎡","structure_material":"木造平屋建","registered":"2004.03.02(平成16.03.02)","register_no":"27 － 0280","desc":"主屋玄関の南にあり，玄関との間に木戸塀を設ける。桁行５間梁間２間の南３間分が炭蔵，北が綿蔵である。土蔵造平屋建，切妻造，桟瓦葺で，東側は腕木で軒を出し，２箇所の戸口を開く。炭蔵は土間床，綿蔵は板敷。小屋組は梁に束立てで棟木と母屋を受ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004004"},{"id":"00004146","register_sub_id":"101","register_pk":"105136","name":"武束家住宅主屋","kana":null,"category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大阪市平野区瓜破東5-1-21","lat":34.60144,"lng":135.5563045,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、瓦葺、建築面積227㎡","structure_material":"木造2階建","registered":"2004.06.09(平成16.06.09)","register_no":"27 － 0289","desc":"瓜破集落の中心部にある大型民家。南面し東半に広い土間を取り，西半床上部は整形四間取りを基本とし，北西部はさらに南北２室に分ける。土間境に広敷を取り，座敷への上り口敷居を突き止め溝とするなど古制を残す。大阪近郊地主層の屋敷の姿を良くとどめる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004146"},{"id":"00000449","register_sub_id":"101","register_pk":"101439","name":"高谷家住宅","kana":null,"category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"low","period":"大正","pref":"大阪府","address":"大阪府大阪市住吉区帝塚山中3-8-18","lat":34.62064645,"lng":135.49961855,"geo_status":"db","era":"大正13頃","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"鉄骨造2階建，銅板葺，建築面積86㎡","structure_material":"鉄骨造2階建","registered":"1998.01.16(平成10.01.16)","register_no":"27 － 0030","desc":"大正期に開発された住宅地内に建つ初期の洋風住宅。鉄骨構造で外壁はコンクリートブロック積みとする。内部は，和洋併用で全体的に質の高い意匠にまとめる。風見鶏付の銅板切妻大屋根は，この地域のランドマーク的存在で広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000449"},{"id":"00006685","register_sub_id":"101","register_pk":"107668","name":"萬代家住宅主屋","kana":null,"category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市阿倍野区播磨町1-1-18","lat":34.62519976,"lng":135.51004093,"geo_status":"db","era":"昭和14","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"木造2階建、瓦葺、建築面積186㎡","structure_material":"木造2階建","registered":"2007.12.05(平成19.12.05)","register_no":"27 － 0432","desc":"昭和初期造成の区画整理事業地に建つ比較的規模の大きい住宅建築で、主体部は中廊下型、外観大壁造の和風とし、玄関東方にルスティカ仕上げ、石貼の洋室を配し、北西隅に蔵としての物置を配する。設計施工は、高橋溪一が経営する高橋工務店で、建築届書を残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006685"},{"id":"00004152","register_sub_id":"101","register_pk":"105142","name":"榎原家住宅旧米蔵","kana":null,"category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府吹田市豊津町25-2","lat":34.76011535,"lng":135.49207315,"geo_status":"db","era":"明治23頃","year":1890,"year_source":"db","year_min":1890,"year_max":1890,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積23㎡","structure_material":"土蔵造平屋建","registered":"2004.06.09(平成16.06.09)","register_no":"27 － 0295","desc":"長屋門の南，屋敷南東隅に建つ。土蔵造平屋建，桟瓦葺で，内部は間仕切を設けず１室とする。低い切石積基礎上に建ち，軒蛇腹は回さないが，軒裏，螻羽とも漆喰で塗込め，南面の高い位置に小窓を開く。小規模で簡素な造りだが屋敷正面の構えに欠かせない存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004152"},{"id":"00004150","register_sub_id":"101","register_pk":"105140","name":"榎原家住宅長屋門","kana":null,"category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府吹田市豊津町25-2","lat":34.76016686,"lng":135.49207906,"geo_status":"db","era":"江戸末期／明治初期改造","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、建築面積42㎡","structure_material":"木造","registered":"2004.06.09(平成16.06.09)","register_no":"27 － 0293","desc":"東側の街路に面して建つ長屋門。南半に鏡柱を立て冠木を置いて門口を構え，北に居室部を設け，南端は旧米蔵，北端は東土蔵に接する。門口部分は屋根を一段下げるとともに，軒を大きく持ち出して変化を付ける。簡素ながら屋敷の正面構えを構成する中心的建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004150"},{"id":"00004151","register_sub_id":"101","register_pk":"105141","name":"榎原家住宅東土蔵","kana":null,"category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府吹田市豊津町25-2","lat":34.760242,"lng":135.492096,"geo_status":"db","era":"明治7","year":1874,"year_source":"db","year_min":1874,"year_max":1874,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積28㎡","structure_material":"土蔵造2階建","registered":"2004.06.09(平成16.06.09)","register_no":"27 － 0294","desc":"主屋東，屋敷北東隅に建つ。土蔵造２階建，本瓦葺で，外部は腰を石張，軒に小さな蛇腹を造り東面に小窓を並べる。内部は低い位置に床梁を渡し２階床を張り，２階は大きく湾曲した梁を用いふところを確保する。たちの低い外観は長屋門との連続性が強調される。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004151"},{"id":"00004149","register_sub_id":"101","register_pk":"105139","name":"榎原家住宅主屋","kana":null,"category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府吹田市豊津町25-2","lat":34.76025,"lng":135.491959,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積183㎡","structure_material":"木造平屋建","registered":"2004.06.09(平成16.06.09)","register_no":"27 － 0292","desc":"ほぼ正方形の宅地の北半に南面して建つ。つし２階のある入母屋造の上屋に下屋を回し，全体を桟瓦葺とする。間口約２０ｍに及び，複雑な間取で土間を細かく仕切るなど新傾向を示すが，大戸口脇下店に格子窓を開けるなど，大阪庄屋クラスの民家の伝統を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004149"},{"id":"00004153","register_sub_id":"101","register_pk":"105143","name":"榎原家住宅西土蔵","kana":null,"category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府吹田市豊津町25-2","lat":34.76029366,"lng":135.49184652,"geo_status":"db","era":"明治23","year":1890,"year_source":"db","year_min":1890,"year_max":1890,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積18㎡","structure_material":"土蔵造2階建","registered":"2004.06.09(平成16.06.09)","register_no":"27 － 0296","desc":"屋敷の北西隅，主屋の西に隣接し，南面に蔵前を付し主屋奥の座敷に直接連絡する。土蔵造２階建，本瓦葺で，高い切石積基礎上に建ち，軒蛇腹は回さないが軒裏，螻羽とも塗込め，壁面には高く舟板を張る。小規模だがたちが高い特徴ある姿は周囲でも一際目立つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004153"},{"id":"00007269","register_sub_id":"101","register_pk":"108251","name":"奥野家住宅門長屋","kana":null,"category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府豊中市中桜塚2-422-1","lat":34.778633,"lng":135.468979,"geo_status":"db","era":"江戸後期／平成10改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積33㎡","structure_material":"木造平屋建","registered":"2008.07.08(平成20.07.08)","register_no":"27 － 0498","desc":"敷地西辺の中央に建つ。木造平屋建、入母屋造桟瓦葺で、北側は西の蔵に接続する。南半部を門口として中央に両開の板戸を吊り、北脇に潜戸を開く。北半部は供部屋で、西正面を下見板張として物見格子を付け、屋敷の重厚な表構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007269"},{"id":"00007267","register_sub_id":"101","register_pk":"108249","name":"奥野家住宅東蔵","kana":null,"category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府豊中市中桜塚2-422-1","lat":34.778751,"lng":135.469131,"geo_status":"db","era":"江戸末期／明治後期移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積40㎡","structure_material":"土蔵造2階建","registered":"2008.07.08(平成20.07.08)","register_no":"27 － 0496","desc":"敷地北辺、米蔵の東隣に建つ。桁行７．４ｍ梁間４．４ｍ、土蔵造２階建、切妻造、置屋根形式の桟瓦葺で、南面に桟瓦葺の庇をつける。外壁は中塗仕上げで、腰を竪板張として、他の土蔵と表情を違える。屋敷地の裏手にあって、落ち着いた佇まいをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007267"},{"id":"00006283","register_sub_id":"101","register_pk":"107267","name":"村司家住宅主屋","kana":null,"category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府豊中市蛍池中町2-14-17","lat":34.792965,"lng":135.447037,"geo_status":"db","era":"江戸末期／昭和28頃増築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積107㎡","structure_material":"木造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"27 － 0425","desc":"敷地中央に南面して建つ木造２階建の寄棟造，桟瓦葺。元は整形四間取の茅葺農家で，２階を増築した。１階は座敷６畳と次の間６畳で，南に縁が付く。東半の土間は改装した。２階は数寄屋風の座敷８畳，茶室４畳半等を配す。現在は近代和風住宅の外観を呈す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006283"},{"id":"00004154","register_sub_id":"101","register_pk":"105144","name":"榎原家住宅掛塀","kana":null,"category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府吹田市豊津町25-2","lat":34.7603116,"lng":135.49197601,"geo_status":"db","era":"明治23頃","year":1890,"year_source":"db","year_min":1890,"year_max":1890,"year_label":null,"structure":"木造、瓦葺、延長21m","structure_material":"木造","registered":"2004.06.09(平成16.06.09)","register_no":"27 － 0297","desc":"主屋の背後，宅地の北面を区切る塀。高い切石積基礎上に１間毎に柱を立て，腕木で出桁を受け桟瓦葺屋根を架け，ほぼ中央に出入口を開く。外面は腰に連続して舟板を張り，上の狭い壁面は柱間を漆喰塗とする。堅牢な構えながら水平性を強調し独特の景観を造る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004154"},{"id":"00007271","register_sub_id":"101","register_pk":"108253","name":"奥野家住宅露地門及び高塀","kana":null,"category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府豊中市中桜塚2-422-1","lat":34.77840862,"lng":135.46918144,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"門 木造、瓦葺、間口1.6m 塀 木造、瓦葺、延長16m","structure_material":"門 木造","registered":"2008.07.08(平成20.07.08)","register_no":"27 － 0500","desc":"主屋式台の東側から南に延び、主屋前庭と座敷前庭を区画する。露地門は間口１．６ｍで、両開板戸を吊る。板戸は透欄間を入れ、小脇壁の腰に杉皮を張るなど、数寄屋風を加味して穏やかな表情とする。左右に延びる高塀とともに落ち着いた庭空間を演出している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007271"},{"id":"00011778","register_sub_id":"101","register_pk":"210794","name":"阿江家住宅内蔵","kana":"あえけじゅうたくうちぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和中","pref":"兵庫県","address":"兵庫県加東市下滝野590","lat":34.936856,"lng":134.95628,"geo_status":"db","era":"昭和23年頃","year":1948,"year_source":"db","year_min":1948,"year_max":1948,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積39㎡","structure_material":"土蔵造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"28-0665","desc":"東棟の北に接続する。四・九メートル四方の二階建、切妻造妻入で、蔵前を付ける。正面のみ海鼠壁で他は漆喰仕上げ板張とし、一階は北面に二所丸窓を、二階は東西に一所ずつ片引窓を開ける。戸口の観音扉や土戸には黒漆喰塗を施すなど丁寧な造りの蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011778"},{"id":"00013863","register_sub_id":"101","register_pk":"507821","name":"阿江家住宅米蔵","kana":"あえけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和中","pref":"兵庫県","address":"兵庫県加東市下滝野590","lat":34.936925,"lng":134.95619444,"geo_status":"db","era":"昭和23年頃","year":1948,"year_source":"db","year_min":1948,"year_max":1948,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積68㎡","structure_material":"土蔵造平屋建","registered":"2021.06.24(令和3.06.24)","register_no":"28 － 0766","desc":"道具蔵の西に、ほぼ同規模同形式で南面して建つ。土蔵造平屋建切妻造桟瓦葺で、正面に下屋を付し、脇に大振りの袖壁を設ける。外壁は軒先まで漆喰で塗込める。内部は一室で漆喰仕上の柱間に間柱を密に立てる。道具蔵とともに建ち並ぶ姿が独特の景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013863"},{"id":"00011777","register_sub_id":"101","register_pk":"210793","name":"阿江家住宅主屋北西棟","kana":"あえけじゅうたくしゅおくほくせいとう","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和中","pref":"兵庫県","address":"兵庫県加東市下滝野590","lat":34.936788,"lng":134.956172,"geo_status":"db","era":"昭和23年頃","year":1948,"year_source":"db","year_min":1948,"year_max":1948,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積58㎡","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"28-0664","desc":"南・東棟から廊下を介して建つ。居室となる和室四室を田の字に配する。平屋であるが軒高は高く、持送りで支える小庇を四周に廻らす。東西面の窓は片引で開口が小さく、外壁のほとんどを板張とし、小壁と軒付壁のみ色土壁とする独特の外観を持つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011777"},{"id":"00011776","register_sub_id":"101","register_pk":"210792","name":"阿江家住宅主屋南・東棟","kana":"あえけじゅうたくしゅおくみなみ・ひがしとう","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和中","pref":"兵庫県","address":"兵庫県加東市下滝野590","lat":34.936657,"lng":134.956224,"geo_status":"db","era":"昭和23年頃","year":1948,"year_source":"db","year_min":1948,"year_max":1948,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積209㎡、渡廊下付","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"28-0663","desc":"市街地北西部の加古川沿いに位置する。西面する玄関から応接間、客間、茶の間、台所を一列に並べ、Ｌ字に北へ和室と仏間を繋げる。地松等良材を用い、天井を高く取り、変化に富んだ格天井とするなど、内外部に意匠を凝らす。特色ある近代和風建築の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011776"},{"id":"00013862","register_sub_id":"101","register_pk":"507697","name":"阿江家住宅道具蔵","kana":"あえけじゅうたくどうぐくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和中","pref":"兵庫県","address":"兵庫県加東市下滝野590","lat":34.93687222,"lng":134.95606667,"geo_status":"db","era":"昭和23年頃","year":1948,"year_source":"db","year_min":1948,"year_max":1948,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積68㎡","structure_material":"土蔵造平屋建","registered":"2021.06.24(令和3.06.24)","register_no":"28 － 0765","desc":"旧滝野町市街地に位置し、既登録の主屋の北に南面して建つ。土蔵造平屋建切妻造桟瓦葺で、正面に下屋を付し、脇に大振りの袖壁を設け、軒先まで漆喰で塗込める。内部は板敷の一室で壁は漆喰仕上に間柱を密に立てる。火災の教訓を踏まえた独特な外観をみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013862"},{"id":"00005327","register_sub_id":"101","register_pk":"106315","name":"赤木家住宅石垣","kana":"あかぎけじゅうたくいしがき","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県豊岡市引野972","lat":35.49789146,"lng":134.81788555,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"石造、延長202m","structure_material":"石造","registered":"2006.03.02(平成18.03.02)","register_no":"28 － 0237","desc":"敷地周囲を廻る石垣で，高さ０．９ｍから１．７ｍの範囲で，土蔵や木造塀の基礎を構成する。場所によって積み方が異なり，東辺南側及び南辺西半を玄武岩切石の乱積み，東辺北側及び北辺，西辺，南辺東半を切石布積みとし，敷地周辺の景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005327"},{"id":"00005322","register_sub_id":"101","register_pk":"106310","name":"赤木家住宅表門","kana":"あかぎけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県豊岡市引野972","lat":35.49750965,"lng":134.81831155,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造、瓦葺、間口2.3m、石段付","structure_material":"木造","registered":"2006.03.02(平成18.03.02)","register_no":"28 － 0232","desc":"敷地東辺の作業小屋と番人小屋の間にあり，間口２間の腕木門で切妻造，桟瓦葺とする。柱を８寸角とし，鋲を３段に打った両開き板戸が取り付き，北側に潜り戸を付ける。表側に５段の切り石段を設け，道路より高さ０．９ｍ上に建ち，屋敷の表構えを構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005322"},{"id":"00005312","register_sub_id":"101","register_pk":"106300","name":"赤木家住宅主屋","kana":"あかぎけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県豊岡市引野972","lat":35.49760165,"lng":134.81813973,"geo_status":"db","era":"明治3","year":1870,"year_source":"db","year_min":1870,"year_max":1870,"year_label":null,"structure":"木造2階一部3階建、瓦葺、建築面積278㎡","structure_material":"木造2階一部3階建","registered":"2006.03.02(平成18.03.02)","register_no":"28 － 0222","desc":"東面敷地の中央北東寄りに位置し，桁行１０間，梁間７間で，木造２階建，南側を切妻造，北側を入母屋造とし，瓦葺とする。１階を六間取として，２階にも座敷をとり，３階を養蚕室とする。越屋根を上げ，式台玄関を構え，農家建築として質，規模共に秀でる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005312"},{"id":"00005324","register_sub_id":"101","register_pk":"106312","name":"赤木家住宅中門及び塀","kana":"あかぎけじゅうたくちゅうもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県豊岡市引野972","lat":35.4976726,"lng":134.81827443,"geo_status":"db","era":"明治末期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"中門 木造、瓦葺、間口1.8m、塀 木造、瓦葺、延長6.3m、便所付","structure_material":"中門 木造","registered":"2006.03.02(平成18.03.02)","register_no":"28 － 0234","desc":"主屋の東側に位置し，玄関前庭と主屋北側の庭園を仕切る。中門は柱間１間の腕木門で切妻造，桟瓦葺とする。両脇に瓦屋根付きの木造の塀を，西側は主屋，東側は敷地境の厠まで延ばす。厠は半坪の規模で切妻造，桟瓦葺とする。主屋玄関前の景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005324"},{"id":"00005316","register_sub_id":"101","register_pk":"106304","name":"赤木家住宅西米蔵","kana":"あかぎけじゅうたくにしこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県豊岡市引野972","lat":35.49766604,"lng":134.81786076,"geo_status":"db","era":"明治末期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"土蔵造2階建、瓦葺、建築面積49㎡","structure_material":"土蔵造2階建","registered":"2006.03.02(平成18.03.02)","register_no":"28 － 0226","desc":"西味噌蔵の南側に接して建ち，桁行３間半，梁間３間の規模で，土蔵造２階建，切妻造，桟瓦葺とし，東側に奥行１間の庇を付ける。内部は壁及び床を板張りとし，東側に両開きの土戸を開き，１，２階の西面と南面に窓を付け，敷地西側の土蔵群を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005316"},{"id":"00005317","register_sub_id":"101","register_pk":"106305","name":"赤木家住宅西倉庫","kana":"あかぎけじゅうたくにしそうこ","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"明治","pref":"兵庫県","address":"兵庫県豊岡市引野972","lat":35.49762404,"lng":134.81785766,"geo_status":"db","era":"明治末期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"木造平屋建、瓦葺、建築面積29㎡","structure_material":"木造平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"28 － 0227","desc":"西米蔵の南側に接して建ち，桁行３間，梁間２間の規模で，木造平屋建，切妻造，桟瓦葺とする。北面に壁を設けず，西米蔵の外壁を兼用し，その他三方の壁に開口部を設け，西壁を板張りとする。屋根を木造のトラスを組んで造り，敷地西側の土蔵群を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005317"},{"id":"00005314","register_sub_id":"101","register_pk":"106302","name":"赤木家住宅西土蔵","kana":"あかぎけじゅうたくにしどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県豊岡市引野972","lat":35.49784793,"lng":134.81788513,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"土蔵造2階建、瓦葺、建築面積148㎡","structure_material":"土蔵造2階建","registered":"2006.03.02(平成18.03.02)","register_no":"28 － 0224","desc":"敷地西側の北端に位置し，桁行１２間半，梁間２間の規模で，土蔵造２階建，切妻造，桟瓦葺，置屋根形式とする。東側に奥行１間の庇を付け，その北端を木造倉庫とする。内部は４つに分けられ，それぞれに両開きの扉を付ける。壁は漆喰塗の上を板張りとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005314"},{"id":"00005315","register_sub_id":"101","register_pk":"106303","name":"赤木家住宅西味噌蔵","kana":"あかぎけじゅうたくにしみそぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県豊岡市引野972","lat":35.49771818,"lng":134.81786314,"geo_status":"db","era":"明治末期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"木造平屋建、瓦葺、建築面積39㎡","structure_material":"木造平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"28 － 0225","desc":"西土蔵の南側に接して建ち，桁行４間半，梁間２間の規模で，木造平屋建，切妻造，桟瓦葺とし，東側に奥行半間の庇を付ける。内部は２室に分けられ，それぞれ両引き戸を付ける。西側敷地境に窓３箇所を開き，敷地西側の連続した蔵の景観を作り出している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005315"},{"id":"00005318","register_sub_id":"101","register_pk":"106306","name":"赤木家住宅西物置","kana":"あかぎけじゅうたくにしものおき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"兵庫県","address":"兵庫県豊岡市引野972","lat":35.49740448,"lng":134.8178369,"geo_status":"db","era":"明治末期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"木造平屋建、瓦葺、建築面積18㎡","structure_material":"木造平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"28 － 0228","desc":"敷地西面の南端近くに位置し，桁行３間，梁間１間半の規模で，木造平屋建，切妻造，桟瓦葺とする。西面は開口部を設けず板壁として，南側に掃出しを設け，東壁面を腰板壁として格子窓を付け，北面に出入口を設ける。敷地西辺の景観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005318"},{"id":"00005323","register_sub_id":"101","register_pk":"106311","name":"赤木家住宅西門","kana":"あかぎけじゅうたくにしもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県豊岡市引野972","lat":35.49745986,"lng":134.81781873,"geo_status":"db","era":"明治末期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"木造、瓦葺、間口1.7m","structure_material":"木造","registered":"2006.03.02(平成18.03.02)","register_no":"28 － 0233","desc":"敷地西辺の南方に位置し，西物置と西倉庫の間に棟をやや低くして建つ。間口２間の規模で，木造の腕木門で切妻造，桟瓦葺，中央１間に両開き戸を開き，両脇を板壁とする。屋敷の裏門に当たり，西辺に並ぶ土蔵等と共に，敷地背面の屋敷景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005323"},{"id":"00005313","register_sub_id":"101","register_pk":"106301","name":"赤木家住宅離れ（北涼館）","kana":"あかぎけじゅうたくはなれ（ほくりょうかん）","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県豊岡市引野972","lat":35.49776893,"lng":134.81803504,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積68㎡","structure_material":"木造平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"28 － 0223","desc":"主屋の北西に位置し，廊下で主屋と接続。桁行６間半，梁間３間の規模で，木造平屋建，切妻造，桟瓦葺とする。８畳間２室の続き間座敷で，書院造の形式を整え，南と東側に畳縁を廻し，化粧軒裏，杉丸太の出桁造とし，深い軒を造り，全体に上質の造作とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005313"},{"id":"00005321","register_sub_id":"101","register_pk":"106309","name":"赤木家住宅番人小屋","kana":"あかぎけじゅうたくばんにんごや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"兵庫県","address":"兵庫県豊岡市引野972","lat":35.49754072,"lng":134.81831011,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積6.0㎡","structure_material":"木造平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"28 － 0231","desc":"作業所北側の表門北側に位置し，桁行１間半，梁間１間の規模で，木造平屋建，寄棟造，桟瓦葺とする。西側を出入口とし，東側に格子窓を開く。腰を竪板張りとし，柱間を漆喰壁とする真壁構造とする。表門の横に位置し，屋敷の表構えを構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005321"},{"id":"00005320","register_sub_id":"101","register_pk":"106308","name":"赤木家住宅東作業場","kana":"あかぎけじゅうたくひがしさぎょうば","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"兵庫県","address":"兵庫県豊岡市引野972","lat":35.49743059,"lng":134.81822842,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積174㎡","structure_material":"木造2階建","registered":"2006.03.02(平成18.03.02)","register_no":"28 － 0230","desc":"東籾蔵の北側に建ち，桁行７間，梁間２間半の規模とし，木造２階建，切妻造，桟瓦葺で，南端を作業場土間とする。北側に床上部を設けて，その西側に牛舎，外便所を付属し，東籾蔵との間に物置を設ける。２階を板の間の倉庫とし，敷地東側の景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005320"},{"id":"00005319","register_sub_id":"101","register_pk":"106307","name":"赤木家住宅東籾蔵","kana":"あかぎけじゅうたくひがしもみぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県豊岡市引野972","lat":35.49731562,"lng":134.81823079,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造平屋建、瓦葺、建築面積16㎡","structure_material":"土蔵造平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"28 － 0229","desc":"敷地南東の隅に位置し，桁行２間，梁間２間の土蔵造平屋建，切妻造，桟瓦葺の置屋根形式で，東半に２階床を設ける。内壁を板張りとし，年貢米を収納する蔵として使われた。平入の西側に両開き土戸を付け，東面に窓を開き，外壁漆喰塗の整った形式を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005319"},{"id":"00005325","register_sub_id":"101","register_pk":"106313","name":"赤木家住宅塀一","kana":"あかぎけじゅうたくへいいち","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県豊岡市引野972","lat":35.49789883,"lng":134.81827358,"geo_status":"db","era":"明治末期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"木造、瓦葺、延長68m","structure_material":"木造","registered":"2006.03.02(平成18.03.02)","register_no":"28 － 0235","desc":"敷地東辺の番人小屋北側及び北辺に廻る。桟瓦葺の屋根付きの木造真壁造の塀である。柱を半間毎に建て，腰を焼き杉の竪板張りとし，その上を，玄関前庭に面する壁は横桟入りの透かし欄間とし，主屋北の庭園に面した壁は漆喰塗とし，一部を透かし欄間とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005325"},{"id":"00005326","register_sub_id":"101","register_pk":"106314","name":"赤木家住宅塀二","kana":"あかぎけじゅうたくへいに","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県豊岡市引野972","lat":35.49729679,"lng":134.81797594,"geo_status":"db","era":"明治末期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"木造、鉄板葺、延長40m","structure_material":"木造","registered":"2006.03.02(平成18.03.02)","register_no":"28 － 0236","desc":"敷地南辺の東端東籾蔵以西及び南西隅から西物置まで廻り，鉄板葺屋根付きの木造真壁造の塀である。柱を半間毎に建て，敷地南辺西半は腰を竪板張り，その上を中塗り仕上げとし，その他を竪板張り仕上げとする。広大な敷地周辺の景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005326"},{"id":"00010018","register_sub_id":"101","register_pk":"196165","name":"芥田家住宅主屋","kana":"あくたけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県姫路市野里寺町24","lat":34.84431194,"lng":134.70058211,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造2階建、瓦葺、建築面積165㎡","structure_material":"木造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"28 － 0583","desc":"野里街道に東面して表屋を構え、後方に玄関と坪庭を介して居住部を建てる。表屋の下屋に長い差鴨居を通してガラス戸をたて、二階は出桁造で塗込とし、虫籠窓と鉄格子窓を穿つ。居住部は南土間で、上手に二列に居室を配する。当地における表屋造町家の希少例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010018"},{"id":"00010019","register_sub_id":"101","register_pk":"196166","name":"芥田家住宅土蔵","kana":"あくたけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県姫路市野里寺町24","lat":34.84440417,"lng":134.70037248,"geo_status":"db","era":"嘉永3","year":1850,"year_source":"db","year_min":1850,"year_max":1850,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積15㎡","structure_material":"土蔵造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"28 － 0584","desc":"主屋の後方に裏庭を挟んで南北棟で建つ。土蔵造二階建、桁行三・九メートル梁間三・九メートル、切妻造本瓦葺で、東面に戸口を開き、下屋を設ける。外壁漆喰塗で鉢巻を廻らし、腰を海鼠壁とし、二階東面にも窓を開く。野里地区において近世に遡る希少な土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010019"},{"id":"00010020","register_sub_id":"101","register_pk":"196167","name":"芥田家住宅離れ座敷兼土蔵","kana":"あくたけじゅうたくはなれざしきけんどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県姫路市野里寺町24","lat":34.84436128,"lng":134.70035493,"geo_status":"db","era":"大正9","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積12㎡","structure_material":"土蔵造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"28 － 0585","desc":"主屋後方に南北棟で建つ。土蔵造二階建、桁行三・七メートル梁間二・九メートル、切妻造桟瓦葺である。一階はトコ付の四畳半で、トコや軒に竹を多用するなど数寄屋風意匠とする。二階は日用品の蔵で、登梁形式の小屋を現す。離れと蔵を複合させた独特な建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010020"}];
